-- Zuelen production schema baseline
--
-- Generated 2026-10-09 from the production Supabase project (Postgres 17.6) by reading the
-- system catalogs (pg_get_functiondef, pg_get_constraintdef, pg_get_indexdef, pg_policies,
-- aclexplode). It reproduces the public and app_private schemas as they were after the last
-- recorded migration 20260922105445 plus the changes applied without a history entry
-- (see db/baseline/README.md).
--
-- Target: a fresh Supabase database (auth, storage, extensions schemas and the anon,
-- authenticated and service_role roles already exist).

set check_function_bodies = off;
set client_min_messages = warning;

create extension if not exists pgcrypto with schema extensions;
create extension if not exists "uuid-ossp" with schema extensions;
create extension if not exists http with schema extensions;
create extension if not exists pg_net with schema extensions;

create schema if not exists app_private;

