create table public.stripe_webhook_events (
  event_id text not null,
  event_type text not null,
  processed_at timestamp with time zone default now() not null,
  status text default 'processed'::text not null,
  processing_started_at timestamp with time zone,
  last_error text
);

create table public.tax_events (
  id uuid default gen_random_uuid() not null,
  organization_id uuid not null,
  company_id uuid not null,
  source_document_id uuid,
  authority text default 'ACD'::text not null,
  tax_type text not null,
  tax_year integer,
  amount numeric(18,2),
  due_date date,
  reference text,
  status text default 'open'::text not null,
  metadata jsonb default '{}'::jsonb not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  bank_transaction_id uuid
);

create table public.transactional_email_deliveries (
  delivery_key text not null,
  kind text not null,
  status text default 'processing'::text not null,
  external_id text,
  processing_started_at timestamp with time zone default now() not null,
  sent_at timestamp with time zone,
  last_error text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null
);

create table public.user_profiles (
  user_id uuid not null,
  full_name text,
  avatar_path text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  locale text default 'en'::text not null,
  professional_email_updates boolean default true not null
);

-- ---------------------------------------------------------------------------
-- Functions
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION app_private.accountant_profile_is_public(target_profile_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'app_private'
AS $function$
  select exists (
    select 1
    from public.accountant_profiles p
    join public.accountant_listing_subscriptions s on s.profile_id = p.id
    where p.id = target_profile_id
      and p.approval_status = 'approved'
      and (
        s.status = 'active'
        or (s.status = 'trialing' and (s.trial_end is null or s.trial_end > now()))
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION app_private.add_organization_owner_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  insert into public.organization_members (organization_id, user_id, role)
  values (new.id, new.owner_id, 'owner')
  on conflict (organization_id, user_id) do update set role = 'owner';
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION app_private.audit_source_transaction_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  v_event text;
  v_metadata jsonb := '{}'::jsonb;
begin
  if tg_op='INSERT' then
    v_event:='source_transaction.created';
    v_metadata:=jsonb_build_object(
      'direction',new.direction,
      'amount_gross',new.amount_gross,
      'currency',new.currency,
      'source_type',new.source_type,
      'classification_status',new.classification_status
    );
    insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
    values(new.organization_id,new.company_id,auth.uid(),v_event,'source_transaction',new.id,v_metadata);
    return new;
  elsif tg_op='DELETE' then
    -- Safe-delete RPCs already write a richer deletion event including reversal metadata.
    return old;
  end if;

  if old.classification_status is distinct from new.classification_status then
    if new.classification_status='posted' then
      v_event:='source_transaction.posted';
    else
      v_event:='source_transaction.status_changed';
    end if;
    v_metadata:=jsonb_build_object('from',old.classification_status,'to',new.classification_status);
    insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
    values(new.organization_id,new.company_id,auth.uid(),v_event,'source_transaction',new.id,v_metadata);
  end if;

  if old.exchange_rate_to_base is distinct from new.exchange_rate_to_base and new.exchange_rate_to_base is not null then
    insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
    values(new.organization_id,new.company_id,auth.uid(),'source_transaction.exchange_rate_set','source_transaction',new.id,
      jsonb_build_object('currency',new.currency,'exchange_rate_to_base',new.exchange_rate_to_base));
  end if;

  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION app_private.billable_team_seats(p_organization_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_professional integer;
  v_other integer;
  v_pending_professional integer;
  v_pending_other integer;
begin
  select
    count(*) filter (where om.role in ('accountant','bookkeeper')),
    count(*) filter (where om.role in ('admin','viewer') and om.user_id<>o.owner_id)
  into v_professional,v_other
  from public.organization_members om
  join public.organizations o on o.id=om.organization_id
  where om.organization_id=p_organization_id;

  select
    count(*) filter (where oi.role in ('accountant','bookkeeper')),
    count(*) filter (where oi.role in ('admin','viewer'))
  into v_pending_professional,v_pending_other
  from public.organization_invitations oi
  where oi.organization_id=p_organization_id and oi.status='pending' and oi.expires_at>now();

  return greatest(0,coalesce(v_professional,0)+coalesce(v_pending_professional,0)-1)
    + coalesce(v_other,0)+coalesce(v_pending_other,0);
end;
$function$
;

