CREATE OR REPLACE FUNCTION app_private.enforce_invitation_seat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_purchased integer := 0;
  v_billable integer := 0;
  v_professional_count integer := 0;
  v_increment integer := 1;
  v_source text;
begin
  select coalesce(s.additional_seats,0),s.billing_source into v_purchased,v_source
  from public.organization_subscriptions s where s.organization_id=new.organization_id;

  if v_source='internal' then return new; end if;

  v_billable := app_private.billable_team_seats(new.organization_id);
  if new.role in ('accountant','bookkeeper') then
    select (
      (select count(*) from public.organization_members om where om.organization_id=new.organization_id and om.role in ('accountant','bookkeeper'))
      +
      (select count(*) from public.organization_invitations oi where oi.organization_id=new.organization_id and oi.status='pending' and oi.expires_at>now() and oi.role in ('accountant','bookkeeper'))
    ) into v_professional_count;
    if coalesce(v_professional_count,0)=0 then v_increment:=0; end if;
  end if;

  if v_billable + v_increment > v_purchased then
    raise exception 'ZU_SEAT_LIMIT:%:%',v_billable,v_purchased using errcode='P0001';
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION app_private.enforce_member_seat_after_role_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_purchased integer := 0;
  v_billable integer := 0;
  v_source text;
begin
  if new.role is not distinct from old.role then return new; end if;
  select coalesce(s.additional_seats,0),s.billing_source into v_purchased,v_source
  from public.organization_subscriptions s where s.organization_id=new.organization_id;
  if v_source='internal' then return new; end if;
  v_billable := app_private.billable_team_seats(new.organization_id);
  if v_billable > v_purchased then
    raise exception 'ZU_SEAT_LIMIT:%:%',v_billable,v_purchased using errcode='P0001';
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION app_private.enforce_usage_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_metric text := tg_argv[0];
  v_org uuid;
begin
  v_org := new.organization_id;
  if not app_private.is_premium(v_org) then
    perform public.assert_usage_available(v_org,v_metric,1);
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION app_private.guard_accountant_review_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'app_private'
AS $function$
begin
  if auth.uid() is not null then
    if tg_op='INSERT' then
      new.approval_status:='pending'; new.approved_at:=null; new.rejection_reason:=null;
    elsif tg_op='UPDATE' then
      if row(new.full_name,new.firm_name,new.professional_title,new.bio,new.location,new.languages,new.specialties,new.business_types,new.email,new.phone,new.website,new.portfolio_url,new.qualifications,new.client_references,new.years_experience,new.photo_url)
        is distinct from row(old.full_name,old.firm_name,old.professional_title,old.bio,old.location,old.languages,old.specialties,old.business_types,old.email,old.phone,old.website,old.portfolio_url,old.qualifications,old.client_references,old.years_experience,old.photo_url) then
        new.approval_status:='pending'; new.approved_at:=null; new.rejection_reason:=null;
      else
        new.approval_status:=old.approval_status; new.approved_at:=old.approved_at; new.rejection_reason:=old.rejection_reason;
      end if;
    end if;
  end if;
  return new;
end;
$function$
;

