CREATE OR REPLACE FUNCTION app_private.learn_posted_transaction_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
begin
  if new.classification_status='posted' and new.posted_journal_entry_id is not null and (old.classification_status is distinct from 'posted') and new.suggested_account_id is not null then
    perform app_private.learn_transaction_rule(new.id,new.suggested_account_id);
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION app_private.learn_transaction_rule(p_source_transaction_id uuid, p_account_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v_tx public.source_transactions%rowtype; v_norm text;
begin
  select * into v_tx from public.source_transactions where id=p_source_transaction_id;
  if not found or coalesce(trim(v_tx.counterparty_name),'')='' then return; end if;
  v_norm:=app_private.normalize_counterparty(v_tx.counterparty_name);
  if length(v_norm)<3 then return; end if;
  insert into public.classification_rules(organization_id,company_id,normalized_counterparty,direction,company_account_id,vat_treatment,vat_rate,counterparty_country,times_confirmed,created_by,last_used_at)
  values(v_tx.organization_id,v_tx.company_id,v_norm,v_tx.direction,p_account_id,coalesce(v_tx.vat_treatment,'unknown'),v_tx.vat_rate,v_tx.counterparty_country,1,auth.uid(),now())
  on conflict(company_id,normalized_counterparty,direction) do update set
    company_account_id=excluded.company_account_id,
    vat_treatment=case when excluded.vat_treatment<>'unknown' then excluded.vat_treatment else public.classification_rules.vat_treatment end,
    vat_rate=coalesce(excluded.vat_rate,public.classification_rules.vat_rate),
    counterparty_country=coalesce(excluded.counterparty_country,public.classification_rules.counterparty_country),
    times_confirmed=public.classification_rules.times_confirmed+1,
    last_used_at=now(),updated_at=now();
end $function$
;

CREATE OR REPLACE FUNCTION app_private.metric_limit(p_metric text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select case p_metric
    when 'transactions' then 15
    when 'documents' then 3
    when 'invoices' then 3
    when 'bank_imports' then 1
    else null
  end
$function$
;

CREATE OR REPLACE FUNCTION app_private.normalize_counterparty(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
  select trim(regexp_replace(lower(coalesce(p_text,'')), '[^a-z0-9]+', ' ', 'g'))
$function$
;

CREATE OR REPLACE FUNCTION app_private.notify_accountant_review_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  resend_key text;
  recipient_email text;
  locale_code text := 'en';
  subject_line text;
  text_body text;
  html_body text;
  safe_name text;
  safe_reason text;
  cta_url text;
begin
  if new.approval_status is not distinct from old.approval_status then
    return new;
  end if;
  if new.approval_status not in ('approved','rejected') then
    return new;
  end if;

  select u.email into recipient_email
  from auth.users u
  where u.id = new.user_id;
  if recipient_email is null or position('@' in recipient_email) = 0 then
    return new;
  end if;

  select coalesce(up.locale, 'en') into locale_code
  from public.user_profiles up
  where up.user_id = new.user_id;
  locale_code := coalesce(locale_code, 'en');

  select decrypted_secret into resend_key
  from vault.decrypted_secrets
  where name = 'zuelen_resend_review_notifications'
  limit 1;
  if resend_key is null then
    raise warning 'Zuelen review notification secret is missing';
    return new;
  end if;

  safe_name := replace(replace(replace(coalesce(new.full_name, 'there'), '&', '&amp;'), '<', '&lt;'), '>', '&gt;');
  safe_reason := replace(replace(replace(coalesce(new.rejection_reason, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;');
  cta_url := case when new.approval_status = 'approved' then 'https://app.zuelen.lu/professional' else 'https://app.zuelen.lu/professional/profile' end;

  if locale_code = 'fr' then
    if new.approval_status = 'approved' then
      subject_line := 'Votre profil professionnel Zuelen est approuvé';
      text_body := 'Bonjour ' || coalesce(new.full_name, '') || E',\n\nBonne nouvelle : votre profil professionnel Zuelen a été approuvé. Si votre abonnement est éligible, votre profil est maintenant visible dans l’annuaire.\n\nOuvrir mon espace professionnel : ' || cta_url || E'\n\n— L’équipe Zuelen';
      html_body := '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta http-equiv="X-UA-Compatible" content="IE=edge"></head><body style="margin:0;background-color:#f7f8f5;font-family:Arial,Helvetica,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f7f8f5"><tr><td align="center" style="padding-top:36px;padding-right:18px;padding-bottom:36px;padding-left:18px;"><table width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;background-color:#ffffff;border:1px solid #dfe4dc;border-radius:18px;"><tr><td style="padding-top:30px;padding-right:32px;padding-bottom:12px;padding-left:32px;"><img src="https://zuelen.lu/zuelen-icon.png" width="42" height="42" border="0" alt="Zuelen" style="display:block;width:42px;height:42px;"></td></tr><tr><td style="padding-top:12px;padding-right:32px;padding-bottom:8px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:25px;line-height:32px;color:#20231d;font-weight:700;">Profil approuvé ✓</td></tr><tr><td style="padding-top:0;padding-right:32px;padding-bottom:20px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#686d64;">Bonjour ' || safe_name || ', votre profil professionnel a été approuvé par Zuelen. Si votre abonnement est éligible, il est maintenant visible dans l’annuaire.</td></tr><tr><td style="padding-top:0;padding-right:32px;padding-bottom:28px;padding-left:32px;"><table cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#526B43" style="background-color:#526B43;border-radius:10px;"><a href="' || cta_url || '" style="display:inline-block;padding-top:12px;padding-right:18px;padding-bottom:12px;padding-left:18px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:18px;color:#ffffff;text-decoration:none;font-weight:700;">Ouvrir mon espace professionnel</a></td></tr></table></td></tr><tr><td style="border-top:1px solid #edf0eb;padding-top:18px;padding-right:32px;padding-bottom:24px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:11px;line-height:17px;color:#90958c;">Zuelen · Luxembourg business, under control.</td></tr></table></td></tr></table></body></html>';
    else
      subject_line := 'Des modifications sont requises pour votre profil Zuelen';
      text_body := 'Bonjour ' || coalesce(new.full_name, '') || E',\n\nNous avons examiné votre profil professionnel Zuelen et quelques modifications sont nécessaires avant publication.\n\nNote de vérification : ' || coalesce(new.rejection_reason, '') || E'\n\nMettre à jour mon profil : ' || cta_url || E'\n\n— L’équipe Zuelen';
      html_body := '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta http-equiv="X-UA-Compatible" content="IE=edge"></head><body style="margin:0;background-color:#f7f8f5;font-family:Arial,Helvetica,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f7f8f5"><tr><td align="center" style="padding-top:36px;padding-right:18px;padding-bottom:36px;padding-left:18px;"><table width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;background-color:#ffffff;border:1px solid #dfe4dc;border-radius:18px;"><tr><td style="padding-top:30px;padding-right:32px;padding-bottom:12px;padding-left:32px;"><img src="https://zuelen.lu/zuelen-icon.png" width="42" height="42" border="0" alt="Zuelen" style="display:block;width:42px;height:42px;"></td></tr><tr><td style="padding-top:12px;padding-right:32px;padding-bottom:8px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:25px;line-height:32px;color:#20231d;font-weight:700;">Quelques modifications sont nécessaires</td></tr><tr><td style="padding-top:0;padding-right:32px;padding-bottom:14px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#686d64;">Bonjour ' || safe_name || ', nous avons examiné votre profil professionnel. Veuillez effectuer les modifications ci-dessous avant publication.</td></tr><tr><td style="padding-top:0;padding-right:32px;padding-bottom:20px;padding-left:32px;"><table width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#F1F5ED" style="background-color:#F1F5ED;border-radius:10px;padding-top:14px;padding-right:16px;padding-bottom:14px;padding-left:16px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:22px;color:#3F5634;">' || safe_reason || '</td></tr></table></td></tr><tr><td style="padding-top:0;padding-right:32px;padding-bottom:28px;padding-left:32px;"><table cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#526B43" style="background-color:#526B43;border-radius:10px;"><a href="' || cta_url || '" style="display:inline-block;padding-top:12px;padding-right:18px;padding-bottom:12px;padding-left:18px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:18px;color:#ffffff;text-decoration:none;font-weight:700;">Mettre à jour mon profil</a></td></tr></table></td></tr><tr><td style="border-top:1px solid #edf0eb;padding-top:18px;padding-right:32px;padding-bottom:24px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:11px;line-height:17px;color:#90958c;">Zuelen · Luxembourg business, under control.</td></tr></table></td></tr></table></body></html>';
    end if;
  else
    if new.approval_status = 'approved' then
      subject_line := 'Your Zuelen professional profile is approved';
      text_body := 'Hi ' || coalesce(new.full_name, '') || E',\n\nGood news — your Zuelen professional profile has been approved. If your subscription is eligible, your listing is now visible in the directory.\n\nOpen professional workspace: ' || cta_url || E'\n\n— The Zuelen team';
      html_body := '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta http-equiv="X-UA-Compatible" content="IE=edge"></head><body style="margin:0;background-color:#f7f8f5;font-family:Arial,Helvetica,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f7f8f5"><tr><td align="center" style="padding-top:36px;padding-right:18px;padding-bottom:36px;padding-left:18px;"><table width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;background-color:#ffffff;border:1px solid #dfe4dc;border-radius:18px;"><tr><td style="padding-top:30px;padding-right:32px;padding-bottom:12px;padding-left:32px;"><img src="https://zuelen.lu/zuelen-icon.png" width="42" height="42" border="0" alt="Zuelen" style="display:block;width:42px;height:42px;"></td></tr><tr><td style="padding-top:12px;padding-right:32px;padding-bottom:8px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:25px;line-height:32px;color:#20231d;font-weight:700;">Profile approved ✓</td></tr><tr><td style="padding-top:0;padding-right:32px;padding-bottom:20px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#686d64;">Hi ' || safe_name || ', your professional profile has been approved by Zuelen. If your subscription is eligible, it is now visible in the directory.</td></tr><tr><td style="padding-top:0;padding-right:32px;padding-bottom:28px;padding-left:32px;"><table cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#526B43" style="background-color:#526B43;border-radius:10px;"><a href="' || cta_url || '" style="display:inline-block;padding-top:12px;padding-right:18px;padding-bottom:12px;padding-left:18px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:18px;color:#ffffff;text-decoration:none;font-weight:700;">Open professional workspace</a></td></tr></table></td></tr><tr><td style="border-top:1px solid #edf0eb;padding-top:18px;padding-right:32px;padding-bottom:24px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:11px;line-height:17px;color:#90958c;">Zuelen · Luxembourg business, under control.</td></tr></table></td></tr></table></body></html>';
    else
      subject_line := 'Changes are required for your Zuelen profile';
      text_body := 'Hi ' || coalesce(new.full_name, '') || E',\n\nWe reviewed your Zuelen professional profile and need a few changes before it can be published.\n\nReview note: ' || coalesce(new.rejection_reason, '') || E'\n\nUpdate my profile: ' || cta_url || E'\n\n— The Zuelen team';
      html_body := '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta http-equiv="X-UA-Compatible" content="IE=edge"></head><body style="margin:0;background-color:#f7f8f5;font-family:Arial,Helvetica,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f7f8f5"><tr><td align="center" style="padding-top:36px;padding-right:18px;padding-bottom:36px;padding-left:18px;"><table width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;background-color:#ffffff;border:1px solid #dfe4dc;border-radius:18px;"><tr><td style="padding-top:30px;padding-right:32px;padding-bottom:12px;padding-left:32px;"><img src="https://zuelen.lu/zuelen-icon.png" width="42" height="42" border="0" alt="Zuelen" style="display:block;width:42px;height:42px;"></td></tr><tr><td style="padding-top:12px;padding-right:32px;padding-bottom:8px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:25px;line-height:32px;color:#20231d;font-weight:700;">Your profile needs a few changes</td></tr><tr><td style="padding-top:0;padding-right:32px;padding-bottom:14px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#686d64;">Hi ' || safe_name || ', we reviewed your professional profile. Please make the change below before it can be published.</td></tr><tr><td style="padding-top:0;padding-right:32px;padding-bottom:20px;padding-left:32px;"><table width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#F1F5ED" style="background-color:#F1F5ED;border-radius:10px;padding-top:14px;padding-right:16px;padding-bottom:14px;padding-left:16px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:22px;color:#3F5634;">' || safe_reason || '</td></tr></table></td></tr><tr><td style="padding-top:0;padding-right:32px;padding-bottom:28px;padding-left:32px;"><table cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#526B43" style="background-color:#526B43;border-radius:10px;"><a href="' || cta_url || '" style="display:inline-block;padding-top:12px;padding-right:18px;padding-bottom:12px;padding-left:18px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:18px;color:#ffffff;text-decoration:none;font-weight:700;">Update my profile</a></td></tr></table></td></tr><tr><td style="border-top:1px solid #edf0eb;padding-top:18px;padding-right:32px;padding-bottom:24px;padding-left:32px;font-family:Arial,Helvetica,sans-serif;font-size:11px;line-height:17px;color:#90958c;">Zuelen · Luxembourg business, under control.</td></tr></table></td></tr></table></body></html>';
    end if;
  end if;

  perform net.http_post(
    url := 'https://api.resend.com/emails',
    headers := jsonb_build_object(
      'Content-Type','application/json',
      'Authorization','Bearer ' || resend_key,
      'Idempotency-Key', md5(new.id::text || ':' || new.approval_status || ':' || coalesce(new.updated_at::text, now()::text))
    ),
    body := jsonb_build_object(
      'from','Zuelen <notifications@zuelen.lu>',
      'to',jsonb_build_array(recipient_email),
      'subject',subject_line,
      'text',text_body,
      'html',html_body
    ),
    timeout_milliseconds := 5000
  );
  return new;
exception when others then
  raise warning 'Zuelen accountant review notification failed: %', sqlerrm;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION app_private.owns_accountant_profile(target_profile_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'app_private'
AS $function$
  select exists (
    select 1 from public.accountant_profiles p
    where p.id = target_profile_id and p.user_id = auth.uid()
  );
$function$
;

CREATE OR REPLACE FUNCTION app_private.record_usage_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_metric text := tg_argv[0];
begin
  insert into public.organization_usage_events(organization_id,metric,quantity,source_id,created_at)
  values(new.organization_id,v_metric,1,new.id,coalesce(new.created_at,now()));
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION app_private.shares_organization_with(target_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select auth.uid() is not null and exists (
    select 1
    from public.organization_members mine
    join public.organization_members theirs on theirs.organization_id = mine.organization_id
    where mine.user_id = auth.uid()
      and theirs.user_id = target_user_id
  );
$function$
;

CREATE OR REPLACE FUNCTION app_private.subscription_period_bounds(p_organization_id uuid)
 RETURNS TABLE(period_start timestamp with time zone, period_end timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_anchor timestamptz;
  v_current_start timestamptz;
  v_current_end timestamptz;
  v_months integer;
begin
  select s.billing_anchor,s.current_period_start,s.current_period_end
    into v_anchor,v_current_start,v_current_end
  from public.organization_subscriptions s
  where s.organization_id=p_organization_id;

  if v_anchor is null then
    select o.created_at into v_anchor from public.organizations o where o.id=p_organization_id;
  end if;

  if v_current_start is not null and v_current_end is not null and now() >= v_current_start and now() < v_current_end then
    return query select v_current_start,v_current_end;
    return;
  end if;

  v_months := greatest(0,
    (extract(year from age(now(),v_anchor))::integer * 12) + extract(month from age(now(),v_anchor))::integer
  );
  period_start := v_anchor + make_interval(months => v_months);
  if period_start > now() then
    v_months := greatest(0,v_months-1);
    period_start := v_anchor + make_interval(months => v_months);
  end if;
  period_end := v_anchor + make_interval(months => v_months+1);
  return next;
end;
$function$
;

CREATE OR REPLACE FUNCTION app_private.suggest_bank_account(p_company_id uuid, p_direction text, p_counterparty text, p_description text)
 RETURNS TABLE(account_id uuid, confidence numeric, reason text, kind text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  v_text text;
  v_code text;
  v_conf numeric;
  v_reason text;
  v_kind text := 'operating';
begin
  v_text := translate(lower(coalesce(p_counterparty,'') || ' ' || coalesce(p_description,'')), 'àáâäãåçèéêëìíîïñòóôöõùúûüýÿ', 'aaaaaaceeeeiiiinooooouuuuyy');

  if v_text like '%compte courant associ%' or v_text like '%apport associ%' then
    v_code := '4712';
    v_conf := 0.95;
    v_kind := 'shareholder_transfer';
    v_reason := case
      when p_direction='income' then 'Shareholder funding entered the company. Record it on the shareholder current account; any debit balance is reclassified to a shareholder receivable for balance-sheet presentation.'
      else 'Company money was paid to the shareholder. Record it on the shareholder current account; any debit balance is reclassified to a shareholder receivable for balance-sheet presentation.'
    end;
  elsif p_direction='income' and (v_text like '%remb%paiement%electron%' or v_text like '%payment%refund%' or v_text like '%card%refund%' or v_text like '%rembours%carte%') then
    v_code:='485'; v_conf:=0.90; v_kind:='refund_candidate'; v_reason:='Incoming electronic-payment refund detected. Held in suspense until it is matched to the original purchase; it is not treated as new revenue.';
  elsif p_direction='expense' and (v_text like '%upwrkescrow%' or v_text like '%upwork%escrow%' or v_text like '%upwork%') then
    v_code:='61348'; v_conf:=case when v_text like '%upwrkescrow%' or v_text like '%connect%' then 0.95 else 0.93 end; v_reason:='Upwork platform/escrow charge detected; suggested as a professional platform fee.';
  elsif p_direction='income' and (v_text like '%upwork%' or v_text like '%payment escrow inc%') then
    v_code:='7033'; v_conf:=0.97; v_reason:='Upwork/platform service payout detected; suggested as service revenue.';
  elsif p_direction='income' and v_text like '%wolt%luxembourg%' then
    v_code:='7033'; v_conf:=0.98; v_reason:='Wolt business payout detected; suggested as service revenue.';
  elsif p_direction='income' and ((v_text like '%wix.com ltd%' or v_text like '%wix com ltd%') or (v_text like '%wix%' and v_text like '%reiclien%')) then
    v_code:='7033'; v_conf:=0.96; v_reason:='Wix partner/revenue payout detected; suggested as service revenue rather than an expense refund.';
  elsif p_direction='expense' and (v_text like '%google%ads%' or v_text like '%google ads%' or v_text like '%facebook%' or v_text like '%facebk%' or v_text like '%fb.me/ads%' or v_text like '%meta%ads%' or v_text like '%reddit%ads%') then
    v_code:='6151'; v_conf:=0.96; v_reason:='Advertising platform charge detected; suggested as marketing/advertising.';
  elsif p_direction='expense' and (v_text like '%zsfrspb1%' or v_text like '%zsfrsao3%' or v_text like '%forfait mensuel pack pro%' or v_text like '%forfait mensuel%pack%' or v_text like '%monthly%account%package%') then
    v_code:='61333'; v_conf:=0.99; v_kind:='bank_fee'; v_reason:='Recurring POST bank-account package fee detected; use bank account charges and commissions.';
  elsif p_direction='expense' and v_text like '%stripe%' then
    v_code:='61334'; v_conf:=0.94; v_kind:='payment_processor_fee'; v_reason:='Stripe debit/processing fee detected; suggested as charges for electronic means of payment.';
  elsif p_direction='expense' and v_text like '%luxtrust%' then
    v_code:='6132'; v_conf:=0.90; v_reason:='LuxTrust digital identity/certificate service detected; suggested as IT services.';
  elsif p_direction='expense' and (v_text like '%adobe%' or v_text like '%canva%' or v_text like '%openai%' or v_text like '%chatgpt%' or v_text like '%suno%' or v_text like '%anthropic%' or v_text like '%claude%' or v_text like '%clickup%' or v_text like '%wix.com%' or v_text like '%hostinger%' or v_text like '%magnific%' or v_text like '%microsoft%' or v_text like '%google workspace%' or v_text like '%google one%' or v_text like '%apple.com/bill%' or v_text like '%itunes%' or v_text like '%distrokid%' or v_text like '%envato%' or v_text like '%tidio%' or v_text like '%elfsight%' or v_text like '%resume.io%' or v_text like '%resume io%' or v_text like '%ui8.net%' or v_text like '%ui8 net%') then
    v_code:='6132'; v_conf:=case when v_text like '%apple.com/bill%' or v_text like '%itunes%' then 0.76 else 0.92 end; v_reason:='Digital software/subscription/design-service provider detected; suggested as IT services. Review business purpose for generic consumer-platform charges.';
  elsif p_direction='income' and (v_text like '%stripe technology europe%' or v_text like '%stripe technology%') then
    v_code:='485'; v_conf:=0.90; v_kind:='platform_payout'; v_reason:='Stripe payout detected. Held in suspense until matched to Stripe sales, fees and refunds; the net payout is not assumed to be new revenue.';
  elsif p_direction='expense' and (v_text like '%acd-%' or v_text like '%administration des contributions%' or v_text like '%recette esch%') and (v_text like '%avance%' or v_text like '%acompte%' or v_text like '%quarter%') then
    v_code:='42148'; v_conf:=0.90; v_kind:='tax_advance'; v_reason:='ACD tax advance detected. Kept as an ACD tax prepayment/receivable until the notice identifies IRC, ICC, IF or another specific tax; no ordinary operating expense is created.';
  elsif p_direction='expense' and (v_text like '%acd-%' or v_text like '%administration des contributions%' or v_text like '%recette esch%') then
    v_code:='42148'; v_conf:=0.82; v_kind:='tax_payment'; v_reason:='Payment to the ACD detected. Kept temporarily as an ACD tax prepayment until it is matched to the relevant tax notice and exact tax liability.';
  elsif (v_text like '%luxembourg business regis%' or v_text like '%registre de commerce%') and (v_text like '%late%' or v_text like '%retard%' or v_text like '%penal%' or v_text like '%majoration%') then
    v_code:='6481'; v_conf:=0.91; v_kind:='penalty'; v_reason:='RCS/LBR late-payment penalty detected; suggested as fines, sanctions and penalties.';
  elsif v_text like '%luxembourg business regis%' or v_text like '%registre de commerce%' then
    v_code:=null; v_conf:=0.64; v_kind:='registry_payment'; v_reason:='LBR/RCS payment detected. Confirm whether this is a normal filing/administrative charge or a late penalty before posting.';
  elsif v_text like '%pgctstdb%' or v_text like '%zob2bdb%' or v_text like '%pgctstcr%' or v_text like '%zob2bcr%' then
    v_code:=null; v_conf:=null; v_kind:='bank_transfer_unknown'; v_reason:='Bank-transfer operation detected, but the statement contains no reliable beneficiary/sender description. Zuelen will not guess the accounting account from the amount alone.';
  else
    v_code:=null; v_conf:=null; v_reason:=null; v_kind:=null;
  end if;

  if v_code is null then account_id:=null; confidence:=v_conf; reason:=v_reason; kind:=v_kind; return next; return; end if;
  select ca.id into account_id from public.company_accounts ca where ca.company_id=p_company_id and ca.code=v_code and ca.is_active=true limit 1;
  confidence:=v_conf; reason:=v_reason; kind:=v_kind; return next;
end
$function$
;

CREATE OR REPLACE FUNCTION app_private.sync_bank_match_from_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.source_type='bank' and new.source_id is not null and new.classification_status='posted' and new.posted_journal_entry_id is not null then
    update public.bank_transactions set match_status='matched', matched_journal_entry_id=new.posted_journal_entry_id where id=new.source_id and company_id=new.company_id;
  elsif new.source_type='bank' and new.source_id is not null and new.classification_status in ('review','unclassified','classified') then
    update public.bank_transactions set match_status='unmatched', matched_journal_entry_id=null where id=new.source_id and company_id=new.company_id;
  end if;
  return new;
end;
$function$
;

