CREATE OR REPLACE FUNCTION app_private.usage_count(p_organization_id uuid, p_metric text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_start timestamptz;
  v_end timestamptz;
  v_used integer;
begin
  select b.period_start,b.period_end into v_start,v_end
  from app_private.subscription_period_bounds(p_organization_id) b;
  select coalesce(sum(e.quantity),0)::integer into v_used
  from public.organization_usage_events e
  where e.organization_id=p_organization_id
    and e.metric=p_metric
    and e.created_at>=v_start and e.created_at<v_end;
  return coalesce(v_used,0);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.accept_organization_invitation(p_token uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_inv public.organization_invitations%rowtype;
  v_auth_email text := lower(coalesce(auth.jwt()->>'email',''));
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  select * into v_inv
    from public.organization_invitations
   where token=p_token
   for update;
  if not found then raise exception 'Invitation not found'; end if;
  if v_inv.status <> 'pending' then raise exception 'Invitation is no longer active'; end if;
  if v_inv.expires_at < now() then
    update public.organization_invitations set status='expired' where id=v_inv.id;
    raise exception 'Invitation has expired';
  end if;
  if lower(v_inv.email) <> v_auth_email then raise exception 'This invitation belongs to another email address'; end if;

  insert into public.organization_members(organization_id,user_id,role)
  values(v_inv.organization_id,auth.uid(),v_inv.role)
  on conflict(organization_id,user_id) do update set role=excluded.role;

  update public.organization_invitations
     set status='accepted',accepted_by=auth.uid(),accepted_at=now()
   where id=v_inv.id;
  return v_inv.organization_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.apply_ai_bookkeeping_suggestions(p_company_id uuid, p_rows jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v_org uuid; v_row jsonb; v_count integer:=0; v_id uuid;
begin
 select organization_id into v_org from public.companies where id=p_company_id;
 if v_org is null or not app_private.can_bookkeep_org(v_org) then raise exception 'Permission denied'; end if;
 if jsonb_typeof(p_rows)<>'array' then raise exception 'Rows must be an array'; end if;
 for v_row in select value from jsonb_array_elements(p_rows) loop
   v_id=(v_row->>'id')::uuid;
   update public.source_transactions set
     suggested_account_id=nullif(v_row->>'suggested_account_id','')::uuid,
     suggestion_confidence=coalesce(nullif(v_row->>'suggestion_confidence','')::numeric,suggestion_confidence),
     suggestion_reason=coalesce(v_row->>'suggestion_reason',suggestion_reason),
     suggestion_kind=coalesce(v_row->>'suggestion_kind',suggestion_kind),
     ai_classification=coalesce(v_row->'ai_classification',ai_classification),
     ai_analyzed_at=coalesce(nullif(v_row->>'ai_analyzed_at','')::timestamptz,ai_analyzed_at),
     ai_model=coalesce(v_row->>'ai_model',ai_model),
     counterparty_name=coalesce(nullif(v_row->>'counterparty_name',''),counterparty_name),
     counterparty_country=coalesce(nullif(v_row->>'counterparty_country',''),counterparty_country),
     updated_at=now()
   where id=v_id and company_id=p_company_id and classification_status in ('unclassified','review','classified');
   if found then v_count:=v_count+1; end if;
 end loop;
 return v_count;
end
$function$
;

CREATE OR REPLACE FUNCTION public.apply_document_facts_to_transaction(p_link_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  l public.document_transaction_links%rowtype;
  d public.documents%rowtype;
  t public.source_transactions%rowtype;
  v_total numeric;
  v_net numeric;
  v_vat numeric;
  v_rate numeric;
  v_treatment text;
  v_country text;
  v_counterparty text;
begin
  select * into l
  from public.document_transaction_links
  where id=p_link_id;

  if not found or l.source_transaction_id is null then
    raise exception 'Document match is not linked to a transaction';
  end if;

  if not app_private.can_bookkeep_org(l.organization_id) then
    raise exception 'Permission denied';
  end if;

  select * into d from public.documents where id=l.document_id;
  select * into t from public.source_transactions where id=l.source_transaction_id for update;

  if t.classification_status in ('posted','reversed') then
    raise exception 'Posted transactions are immutable; reverse/correct the accounting entry instead';
  end if;

  begin v_total:=nullif(d.extracted_data->>'total','')::numeric; exception when others then v_total:=null; end;
  begin v_net:=nullif(d.extracted_data->>'subtotal','')::numeric; exception when others then v_net:=null; end;
  begin v_vat:=nullif(d.extracted_data->>'vat_amount','')::numeric; exception when others then v_vat:=null; end;
  begin v_rate:=nullif(d.extracted_data->>'vat_rate','')::numeric; exception when others then v_rate:=null; end;

  v_treatment:=coalesce(nullif(d.extracted_data->>'suggested_vat_treatment',''),'unknown');
  v_country:=nullif(coalesce(d.extracted_data->>'issuer_country',d.extracted_data->>'customer_country'),'');
  v_counterparty:=nullif(trim(d.extracted_data->>'transaction_counterparty'),'');
  if v_counterparty is null then
    v_counterparty:=nullif(trim(d.extracted_data->>'issuer_name'),'');
  end if;

  update public.source_transactions
  set
    amount_gross=coalesce(v_total,amount_gross),
    amount_net=coalesce(v_net,case when v_total is not null and v_vat is not null then v_total-v_vat else amount_net end),
    vat_amount=coalesce(v_vat,vat_amount),
    vat_rate=coalesce(v_rate,vat_rate),
    vat_treatment=v_treatment,
    counterparty_country=coalesce(v_country,counterparty_country),
    counterparty_name=coalesce(v_counterparty,counterparty_name),
    updated_at=now()
  where id=t.id;

  perform public.apply_source_transaction_suggestion(t.id);
  perform public.confirm_document_match(l.id);
  return t.id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.apply_source_transaction_suggestion(p_source_transaction_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v_tx public.source_transactions%rowtype;v_s record;v_match record;v_match_count integer;v_rule public.classification_rules%rowtype;v_norm text;v_raw jsonb;v_context text;v_protected boolean:=false;
begin
 select * into v_tx from public.source_transactions where id=p_source_transaction_id;if not found then raise exception 'Transaction not found';end if;if not app_private.can_bookkeep_org(v_tx.organization_id) then raise exception 'Permission denied';end if;
 if v_tx.source_type='bank' and v_tx.source_id is not null then select raw_data into v_raw from public.bank_transactions where id=v_tx.source_id;end if;
 v_context:=concat_ws(' ',nullif(v_tx.description,''),nullif(v_raw->>'operation_code',''),nullif(v_raw->>'communication',''),nullif(v_raw->>'raw_details',''),nullif(v_raw->>'counterparty_address',''),nullif(v_raw->>'counterparty_iban',''));
 select * into v_s from app_private.suggest_bank_account(v_tx.company_id,v_tx.direction,v_tx.counterparty_name,v_context);
 v_protected:=coalesce(v_s.kind,'') in ('shareholder_transfer','tax_advance','tax_payment','payment_processor_fee','refund_candidate','penalty','registry_payment','bank_transfer_unknown','bank_fee','platform_payout');
 if v_protected then update public.source_transactions set suggested_account_id=v_s.account_id,suggestion_confidence=v_s.confidence,suggestion_reason=v_s.reason,suggestion_kind=v_s.kind,updated_at=now() where id=v_tx.id;return v_s.account_id;end if;
 v_norm:=app_private.normalize_counterparty(v_tx.counterparty_name);
 if length(v_norm)>=3 then
  select * into v_rule from public.classification_rules where company_id=v_tx.company_id and direction=v_tx.direction and normalized_counterparty=v_norm order by times_confirmed desc,last_used_at desc limit 1;
  if found then update public.source_transactions set suggested_account_id=v_rule.company_account_id,suggestion_confidence=least(.99,.88+(least(v_rule.times_confirmed,5)*.02)),suggestion_reason='Learned from your previous confirmed treatment for this counterparty.',suggestion_kind='learned_rule',vat_treatment=case when vat_treatment='unknown' then v_rule.vat_treatment else vat_treatment end,vat_rate=coalesce(vat_rate,v_rule.vat_rate),counterparty_country=coalesce(counterparty_country,v_rule.counterparty_country),updated_at=now() where id=v_tx.id;update public.classification_rules set last_used_at=now(),updated_at=now() where id=v_rule.id;return v_rule.company_account_id;end if;
 end if;
 if v_s.account_id is null and v_s.kind is null and v_tx.direction='income' then
  select count(*) into v_match_count from public.source_transactions st where st.company_id=v_tx.company_id and st.direction='expense' and st.occurred_on between (v_tx.occurred_on-45) and v_tx.occurred_on and st.amount_gross=v_tx.amount_gross and st.suggested_account_id is not null and st.id<>v_tx.id;
  if v_match_count=1 then select st.id,st.suggested_account_id into v_match.id,v_match.suggested_account_id from public.source_transactions st where st.company_id=v_tx.company_id and st.direction='expense' and st.occurred_on between (v_tx.occurred_on-45) and v_tx.occurred_on and st.amount_gross=v_tx.amount_gross and st.suggested_account_id is not null and st.id<>v_tx.id limit 1;if v_match.suggested_account_id is not null then v_s.account_id:=v_match.suggested_account_id;v_s.confidence:=0.68;v_s.kind:='refund_candidate';v_s.reason:='Possible supplier refund: this bank inflow exactly matches one recent expense amount. Confirm the merchant/original purchase before posting.';end if;end if;
 end if;
 update public.source_transactions set suggested_account_id=v_s.account_id,suggestion_confidence=v_s.confidence,suggestion_reason=v_s.reason,suggestion_kind=v_s.kind,updated_at=now() where id=v_tx.id;return v_s.account_id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.assert_usage_available(p_organization_id uuid, p_metric text, p_quantity integer DEFAULT 1)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_limit integer;
  v_used integer;
begin
  if not app_private.is_org_member(p_organization_id) then
    raise exception 'Not authorized to use this organization';
  end if;
  if p_quantity < 1 then raise exception 'Usage quantity must be positive'; end if;
  if app_private.is_premium(p_organization_id) then return true; end if;
  v_limit := app_private.metric_limit(p_metric);
  if v_limit is null then return true; end if;
  v_used := app_private.usage_count(p_organization_id,p_metric);
  if v_used + p_quantity > v_limit then
    raise exception 'ZU_BILLING_LIMIT:%:%:%',p_metric,v_used,v_limit using errcode='P0001';
  end if;
  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.bulk_ignore_pending_source_transactions(p_company_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v_org uuid; v_count integer;
begin
  select organization_id into v_org from public.companies where id=p_company_id; if v_org is null or not app_private.can_bookkeep_org(v_org) then raise exception 'Permission denied'; end if;
  update public.bank_transactions bt set match_status='ignored' where bt.company_id=p_company_id and exists(select 1 from public.source_transactions st where st.source_type='bank' and st.source_id=bt.id and st.classification_status in ('unclassified','review','classified'));
  update public.source_transactions set classification_status='ignored',updated_at=now() where company_id=p_company_id and classification_status in ('unclassified','review','classified'); get diagnostics v_count=row_count; return v_count;
end $function$
;

CREATE OR REPLACE FUNCTION public.bulk_ignore_pending_source_transactions_period(p_company_id uuid, p_start date, p_end date)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$ declare v_org uuid; v_count integer; begin select organization_id into v_org from public.companies where id=p_company_id; if v_org is null or not app_private.can_bookkeep_org(v_org) then raise exception 'Permission denied'; end if; update public.bank_transactions bt set match_status='ignored' where bt.company_id=p_company_id and exists(select 1 from public.source_transactions st where st.source_type='bank' and st.source_id=bt.id and st.occurred_on between p_start and p_end and st.classification_status in ('unclassified','review','classified')); update public.source_transactions set classification_status='ignored',updated_at=now() where company_id=p_company_id and occurred_on between p_start and p_end and classification_status in ('unclassified','review','classified'); get diagnostics v_count=row_count; return v_count; end $function$
;

CREATE OR REPLACE FUNCTION public.bulk_post_suggested_source_transactions(p_company_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v_org uuid; v_row record; v_posted integer:=0; v_remaining integer:=0;
begin
  select organization_id into v_org from public.companies where id=p_company_id; if v_org is null or not app_private.can_bookkeep_org(v_org) then raise exception 'Permission denied'; end if;
  for v_row in select st.id,ca.code from public.source_transactions st join public.company_accounts ca on ca.id=st.suggested_account_id where st.company_id=p_company_id and st.classification_status in ('unclassified','review','classified') and st.suggested_account_id is not null and coalesce(st.suggestion_confidence,0)>=0.70 order by st.occurred_on,st.created_at loop perform public.classify_and_post_source_transaction(v_row.id,v_row.code); v_posted:=v_posted+1; end loop;
  select count(*) into v_remaining from public.source_transactions where company_id=p_company_id and classification_status in ('unclassified','review','classified'); return jsonb_build_object('posted',v_posted,'remaining',v_remaining);
end $function$
;

CREATE OR REPLACE FUNCTION public.bulk_post_suggested_source_transactions_period(p_company_id uuid, p_start date, p_end date, p_min_confidence numeric DEFAULT 0.70)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$ declare v_org uuid; v_row record; v_posted integer:=0; v_remaining integer:=0; begin select organization_id into v_org from public.companies where id=p_company_id; if v_org is null or not app_private.can_bookkeep_org(v_org) then raise exception 'Permission denied'; end if; for v_row in select st.id,ca.code from public.source_transactions st join public.company_accounts ca on ca.id=st.suggested_account_id where st.company_id=p_company_id and st.occurred_on between p_start and p_end and st.classification_status in ('unclassified','review','classified') and st.suggested_account_id is not null and coalesce(st.suggestion_confidence,0)>=p_min_confidence order by st.occurred_on,st.created_at loop perform public.classify_and_post_source_transaction(v_row.id,v_row.code); v_posted:=v_posted+1; end loop; select count(*) into v_remaining from public.source_transactions where company_id=p_company_id and occurred_on between p_start and p_end and classification_status in ('unclassified','review','classified'); return jsonb_build_object('posted',v_posted,'remaining',v_remaining); end $function$
;

CREATE OR REPLACE FUNCTION public.bulk_remove_bank_transactions(p_company_id uuid, p_bank_transaction_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v_org uuid; v_id uuid; v_source uuid; v_removed integer:=0; v_blocked integer:=0;
begin
  select organization_id into v_org from public.companies where id=p_company_id;
  if v_org is null or not app_private.can_bookkeep_org(v_org) then raise exception 'Permission denied'; end if;
  if coalesce(array_length(p_bank_transaction_ids,1),0)=0 or array_length(p_bank_transaction_ids,1)>200 then raise exception 'Choose between 1 and 200 bank movements'; end if;
  foreach v_id in array p_bank_transaction_ids loop
    if not exists(select 1 from public.bank_transactions where id=v_id and company_id=p_company_id) then continue; end if;
    if exists(select 1 from public.invoice_payments where bank_transaction_id=v_id) then v_blocked:=v_blocked+1; continue; end if;
    select id into v_source from public.source_transactions where company_id=p_company_id and source_type='bank' and source_id=v_id limit 1;
    if v_source is not null then perform public.delete_source_transaction_safe(v_source); end if;
    update public.bank_transactions set match_status='ignored' where id=v_id and company_id=p_company_id;
    v_removed:=v_removed+1; v_source:=null;
  end loop;
  return jsonb_build_object('removed',v_removed,'blocked',v_blocked);
end
$function$
;

CREATE OR REPLACE FUNCTION public.classify_and_post_source_transaction(p_source_transaction_id uuid, p_account_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
 v_uid uuid:=auth.uid();
 v_tx public.source_transactions%rowtype;
 v_selected public.company_accounts%rowtype;
 v_bank public.company_accounts%rowtype;
 v_vat_in public.company_accounts%rowtype;
 v_vat_out public.company_accounts%rowtype;
 v_company public.companies%rowtype;
 v_period_id uuid;
 v_period_start date;
 v_period_end date;
 v_period_year integer;
 v_entry_id uuid;
 v_entry_number bigint;
 v_net numeric(18,2);
 v_vat_amount numeric(18,2);
 v_description text;
 v_is_expense_refund boolean:=false;
 v_reverse boolean:=false;
 v_fx numeric(18,8);
 v_base_gross numeric(18,2);
 v_base_net numeric(18,2);
 v_base_vat numeric(18,2);
 v_base_currency text;
begin
 if v_uid is null then raise exception 'Authentication required'; end if;
 select * into v_tx from public.source_transactions where id=p_source_transaction_id for update;
 if not found then raise exception 'Source transaction not found or not accessible'; end if;
 if not app_private.can_bookkeep_org(v_tx.organization_id) then raise exception 'You do not have permission to post accounting entries for this company'; end if;
 if v_tx.classification_status='posted' or v_tx.posted_journal_entry_id is not null then raise exception 'This transaction has already been posted'; end if;

 select * into v_company from public.companies where id=v_tx.company_id;
 v_base_currency:=upper(trim(v_company.base_currency::text));
 if upper(trim(v_tx.currency))=v_base_currency then
   v_fx:=1;
 else
   v_fx:=v_tx.exchange_rate_to_base;
   if v_fx is null or v_fx<=0 then
     raise exception 'An exchange rate is required before posting this foreign-currency transaction';
   end if;
 end if;

 select * into v_selected from public.company_accounts where company_id=v_tx.company_id and code=trim(p_account_code) and is_active=true;
 if not found then raise exception 'Accounting category % is not available for this company',p_account_code; end if;

 v_is_expense_refund:=v_tx.direction='income' and v_selected.account_type='expense';
 v_reverse:=v_tx.direction='expense' and v_tx.vat_treatment='eu_b2b_reverse_charge';
 if v_tx.direction='income' and v_selected.account_type not in ('revenue','asset','liability','expense') then raise exception 'Bank inflows must be classified to revenue, a supplier-refund expense account, or an eligible balance-sheet account'; end if;
 if v_tx.direction='expense' and v_selected.account_type not in ('expense','asset','liability') then raise exception 'Bank outflows must be classified to an expense or eligible balance-sheet account'; end if;

 select * into v_bank from public.company_accounts where company_id=v_tx.company_id and code='5131' and is_active=true;
 if not found then raise exception 'The company bank ledger account (5131) is missing'; end if;

 v_vat_amount:=coalesce(v_tx.vat_amount,0);
 v_net:=coalesce(v_tx.amount_net,case when v_reverse then v_tx.amount_gross else round(v_tx.amount_gross-v_vat_amount,2) end);
 v_base_gross:=round(v_tx.amount_gross*v_fx,2);
 v_base_net:=round(v_net*v_fx,2);
 v_base_vat:=round(v_vat_amount*v_fx,2);

 if v_selected.account_type in ('asset','liability') and v_vat_amount<>0 then raise exception 'Balance-sheet transfers cannot carry VAT in this workflow'; end if;
 if v_vat_amount>0 then
   if not v_company.vat_registered then raise exception 'VAT cannot be posted for a company that is not marked as VAT registered'; end if;
   select * into v_vat_in from public.company_accounts where company_id=v_tx.company_id and code='421611' and is_active=true;
   select * into v_vat_out from public.company_accounts where company_id=v_tx.company_id and code='461411' and is_active=true;
   if v_reverse and (v_vat_in.id is null or v_vat_out.id is null) then raise exception 'Reverse-charge VAT accounts are missing'; end if;
   if not v_reverse and (case when v_is_expense_refund or v_tx.direction='expense' then v_vat_in.id else v_vat_out.id end) is null then raise exception 'The required VAT ledger account is missing'; end if;
 end if;

 v_period_year:=extract(year from v_tx.occurred_on)::integer;
 if extract(month from v_tx.occurred_on)::integer<v_company.fiscal_year_start_month then v_period_year:=v_period_year-1; end if;
 v_period_start:=make_date(v_period_year,v_company.fiscal_year_start_month,1);
 v_period_end:=(v_period_start+interval '1 year - 1 day')::date;
 select id into v_period_id from public.accounting_periods where company_id=v_tx.company_id and starts_on=v_period_start and ends_on=v_period_end and status in ('open','soft_closed') limit 1;
 if v_period_id is null then
   insert into public.accounting_periods(organization_id,company_id,starts_on,ends_on,status)
   values(v_tx.organization_id,v_tx.company_id,v_period_start,v_period_end,'open')
   on conflict(company_id,starts_on,ends_on) do nothing;
   select id into v_period_id from public.accounting_periods where company_id=v_tx.company_id and starts_on=v_period_start and ends_on=v_period_end and status in ('open','soft_closed') limit 1;
 end if;
 if v_period_id is null then raise exception 'The accounting period is closed or locked'; end if;

 perform pg_advisory_xact_lock(hashtextextended(v_tx.company_id::text,0));
 select coalesce(max(entry_number),0)+1 into v_entry_number from public.journal_entries where company_id=v_tx.company_id;
 v_description:=coalesce(nullif(v_tx.counterparty_name,''),nullif(v_tx.description,''),case when v_tx.direction='income' then 'Bank inflow' else 'Bank outflow' end);

 insert into public.journal_entries(organization_id,company_id,accounting_period_id,entry_number,entry_date,document_date,description,source_type,source_id,status,created_by)
 values(v_tx.organization_id,v_tx.company_id,v_period_id,v_entry_number,v_tx.occurred_on,v_tx.occurred_on,v_description,v_tx.source_type,v_tx.id,'draft',v_uid)
 returning id into v_entry_id;

 if v_tx.direction='income' then
   insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,description,debit,credit,currency,exchange_rate,original_currency,original_debit,original_credit)
   values(v_tx.organization_id,v_entry_id,v_bank.id,v_description,v_base_gross,0,v_base_currency,v_fx,case when upper(trim(v_tx.currency))<>v_base_currency then upper(trim(v_tx.currency)) else null end,case when upper(trim(v_tx.currency))<>v_base_currency then v_tx.amount_gross else null end,0);
   insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,description,debit,credit,currency,exchange_rate,original_currency,original_debit,original_credit)
   values(v_tx.organization_id,v_entry_id,v_selected.id,v_description,0,v_base_net,v_base_currency,v_fx,case when upper(trim(v_tx.currency))<>v_base_currency then upper(trim(v_tx.currency)) else null end,0,case when upper(trim(v_tx.currency))<>v_base_currency then v_net else null end);
   if v_vat_amount>0 then
     if v_is_expense_refund then
       insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,description,debit,credit,currency,exchange_rate,vat_code,vat_rate,vat_amount,original_currency,original_debit,original_credit)
       values(v_tx.organization_id,v_entry_id,v_vat_in.id,'Input VAT reversal',0,v_base_vat,v_base_currency,v_fx,'INPUT_REVERSAL',v_tx.vat_rate,v_base_vat,case when upper(trim(v_tx.currency))<>v_base_currency then upper(trim(v_tx.currency)) else null end,0,case when upper(trim(v_tx.currency))<>v_base_currency then v_vat_amount else null end);
     else
       insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,description,debit,credit,currency,exchange_rate,vat_code,vat_rate,vat_amount,original_currency,original_debit,original_credit)
       values(v_tx.organization_id,v_entry_id,v_vat_out.id,'Output VAT',0,v_base_vat,v_base_currency,v_fx,'OUTPUT',v_tx.vat_rate,v_base_vat,case when upper(trim(v_tx.currency))<>v_base_currency then upper(trim(v_tx.currency)) else null end,0,case when upper(trim(v_tx.currency))<>v_base_currency then v_vat_amount else null end);
     end if;
   end if;
 else
   insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,description,debit,credit,currency,exchange_rate,vat_code,vat_rate,vat_amount,original_currency,original_debit,original_credit)
   values(v_tx.organization_id,v_entry_id,v_selected.id,v_description,v_base_net,0,v_base_currency,v_fx,case when v_reverse then 'RC_BASE' else null end,v_tx.vat_rate,case when v_reverse then v_base_vat else null end,case when upper(trim(v_tx.currency))<>v_base_currency then upper(trim(v_tx.currency)) else null end,case when upper(trim(v_tx.currency))<>v_base_currency then v_net else null end,0);
   if v_vat_amount>0 then
     if v_reverse then
       insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,description,debit,credit,currency,exchange_rate,vat_code,vat_rate,vat_amount,original_currency,original_debit,original_credit)
       values(v_tx.organization_id,v_entry_id,v_vat_in.id,'Reverse-charge input VAT',v_base_vat,0,v_base_currency,v_fx,'RC_INPUT',v_tx.vat_rate,v_base_vat,case when upper(trim(v_tx.currency))<>v_base_currency then upper(trim(v_tx.currency)) else null end,case when upper(trim(v_tx.currency))<>v_base_currency then v_vat_amount else null end,0);
       insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,description,debit,credit,currency,exchange_rate,vat_code,vat_rate,vat_amount,original_currency,original_debit,original_credit)
       values(v_tx.organization_id,v_entry_id,v_vat_out.id,'Reverse-charge output VAT',0,v_base_vat,v_base_currency,v_fx,'RC_OUTPUT',v_tx.vat_rate,v_base_vat,case when upper(trim(v_tx.currency))<>v_base_currency then upper(trim(v_tx.currency)) else null end,0,case when upper(trim(v_tx.currency))<>v_base_currency then v_vat_amount else null end);
     else
       insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,description,debit,credit,currency,exchange_rate,vat_code,vat_rate,vat_amount,original_currency,original_debit,original_credit)
       values(v_tx.organization_id,v_entry_id,v_vat_in.id,'Input VAT',v_base_vat,0,v_base_currency,v_fx,'INPUT',v_tx.vat_rate,v_base_vat,case when upper(trim(v_tx.currency))<>v_base_currency then upper(trim(v_tx.currency)) else null end,case when upper(trim(v_tx.currency))<>v_base_currency then v_vat_amount else null end,0);
     end if;
   end if;
   insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,description,debit,credit,currency,exchange_rate,original_currency,original_debit,original_credit)
   values(v_tx.organization_id,v_entry_id,v_bank.id,v_description,0,v_base_gross,v_base_currency,v_fx,case when upper(trim(v_tx.currency))<>v_base_currency then upper(trim(v_tx.currency)) else null end,0,case when upper(trim(v_tx.currency))<>v_base_currency then v_tx.amount_gross else null end);
 end if;

 perform public.post_journal_entry(v_entry_id);
 update public.source_transactions
 set suggested_account_id=v_selected.id,
     classification_status='posted',
     posted_journal_entry_id=v_entry_id,
     exchange_rate_to_base=v_fx,
     suggestion_kind=case when v_reverse then 'reverse_charge' when v_is_expense_refund then 'expense_refund' else suggestion_kind end,
     updated_at=now()
 where id=v_tx.id;
 return v_entry_id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.confirm_document_match(p_link_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  v_link public.document_transaction_links%rowtype;
begin
  select *
  into v_link
  from public.document_transaction_links
  where id = p_link_id
  for update;

  if not found then
    raise exception 'Match not found';
  end if;

  if not app_private.can_bookkeep_org(v_link.organization_id) then
    raise exception 'Permission denied';
  end if;

  update public.document_transaction_links
  set status = 'rejected',
      updated_at = now()
  where document_id = v_link.document_id
    and id <> v_link.id
    and status = 'suggested';

  update public.document_transaction_links
  set status = 'confirmed',
      updated_at = now()
  where id = v_link.id;

  update public.documents
  set extraction_status = case
    when extraction_status = 'needs_review' then 'complete'
    else extraction_status
  end
  where id = v_link.document_id;

  insert into public.audit_events(
    organization_id,
    company_id,
    actor_user_id,
    event_type,
    entity_type,
    entity_id,
    metadata
  )
  values(
    v_link.organization_id,
    v_link.company_id,
    auth.uid(),
    'document_match_confirmed',
    'document',
    v_link.document_id,
    jsonb_build_object(
      'link_id', v_link.id,
      'source_transaction_id', v_link.source_transaction_id,
      'score', v_link.match_score
    )
  );

  return v_link.id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.consume_password_recovery_rate_limit(p_bucket_key text, p_max_requests integer, p_window_seconds integer)
 RETURNS TABLE(allowed boolean, retry_after_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_window interval;
  v_count integer;
  v_started_at timestamptz;
begin
  if p_bucket_key is null or length(p_bucket_key) < 16 then
    raise exception 'Invalid rate-limit key';
  end if;
  if p_max_requests < 1 or p_max_requests > 100 then
    raise exception 'Invalid rate-limit maximum';
  end if;
  if p_window_seconds < 60 or p_window_seconds > 86400 then
    raise exception 'Invalid rate-limit window';
  end if;

  v_window := make_interval(secs => p_window_seconds);

  insert into app_private.password_recovery_rate_limits as bucket (
    bucket_key, window_started_at, request_count, updated_at
  ) values (
    p_bucket_key, now(), 1, now()
  )
  on conflict (bucket_key) do update
    set window_started_at = case
          when bucket.window_started_at + v_window <= now() then now()
          else bucket.window_started_at
        end,
        request_count = case
          when bucket.window_started_at + v_window <= now() then 1
          else bucket.request_count + 1
        end,
        updated_at = now()
  returning request_count, window_started_at into v_count, v_started_at;

  return query select
    v_count <= p_max_requests,
    case
      when v_count <= p_max_requests then 0
      else greatest(1, ceil(extract(epoch from ((v_started_at + v_window) - now())))::integer)
    end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.consume_security_rate_limit(p_action text)
 RETURNS TABLE(allowed boolean, retry_after_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_window interval;
  v_limit integer;
  v_count integer;
  v_started_at timestamptz;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  select limits.window_size, limits.max_requests
    into v_window, v_limit
  from (values
    ('bank_import'::text, interval '10 minutes', 10),
    ('checkout'::text, interval '10 minutes', 6),
    ('copilot'::text, interval '5 minutes', 30),
    ('document_extract'::text, interval '10 minutes', 10)
  ) as limits(action, window_size, max_requests)
  where limits.action = p_action;

  if v_limit is null then
    raise exception 'Unsupported rate-limit action';
  end if;

  insert into app_private.security_rate_limits as bucket (
    user_id, action, window_started_at, request_count, updated_at
  ) values (
    v_user_id, p_action, now(), 1, now()
  )
  on conflict (user_id, action) do update
    set window_started_at = case
          when bucket.window_started_at + v_window <= now() then now()
          else bucket.window_started_at
        end,
        request_count = case
          when bucket.window_started_at + v_window <= now() then 1
          else bucket.request_count + 1
        end,
        updated_at = now()
  returning request_count, window_started_at into v_count, v_started_at;

  return query select
    v_count <= v_limit,
    case
      when v_count <= v_limit then 0
      else greatest(1, ceil(extract(epoch from ((v_started_at + v_window) - now())))::integer)
    end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.correct_and_reissue_service_invoice(p_invoice_id uuid, p_customer_name text, p_customer_email text, p_customer_country text, p_customer_vat_number text, p_customer_address jsonb, p_issue_date date, p_service_date date, p_due_date date, p_currency text, p_exchange_rate_to_base numeric, p_vat_treatment text, p_lines jsonb, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_old public.sales_invoices%rowtype;
  v_new_id uuid;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select * into v_old from public.sales_invoices where id=p_invoice_id for update;
  if not found then raise exception 'Invoice not found'; end if;
  if not app_private.can_bookkeep_org(v_old.organization_id) then raise exception 'You do not have permission to correct this invoice'; end if;
  if v_old.status <> 'issued' then raise exception 'Only an issued invoice can be corrected with this workflow'; end if;
  if exists(select 1 from public.invoice_payments where invoice_id=v_old.id) then raise exception 'A paid or partially paid invoice requires a credit-note workflow'; end if;

  perform public.void_sales_invoice_safe(v_old.id);
  v_new_id:=public.save_service_invoice_draft(
    v_old.company_id,
    null,
    p_customer_name,
    p_customer_email,
    p_customer_country,
    p_customer_vat_number,
    p_customer_address,
    p_issue_date,
    p_service_date,
    p_due_date,
    p_currency,
    p_exchange_rate_to_base,
    p_vat_treatment,
    p_lines,
    p_notes
  );
  perform public.issue_service_invoice_draft(v_new_id);

  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_old.organization_id,v_old.company_id,v_uid,'invoice.corrected','sales_invoice',v_old.id,
    jsonb_build_object('replacement_invoice_id',v_new_id,'old_invoice_number',v_old.invoice_number,'currency',p_currency,'exchange_rate_to_base',p_exchange_rate_to_base));
  return v_new_id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.correct_manual_invoice_payment_safe(p_payment_id uuid, p_amount numeric, p_paid_on date, p_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_payment public.invoice_payments%rowtype;
  v_invoice_id uuid;
  v_new_payment uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;

  select * into v_payment
  from public.invoice_payments
  where id = p_payment_id
  for update;
  if not found then raise exception 'Payment not found'; end if;

  if not app_private.can_bookkeep_org(v_payment.organization_id) then
    raise exception 'You do not have permission to edit this payment';
  end if;
  if v_payment.bank_transaction_id is not null then
    raise exception 'A bank-matched payment must be corrected from bank reconciliation';
  end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Payment amount must be greater than zero'; end if;
  if p_paid_on is null then raise exception 'Payment date is required'; end if;

  v_invoice_id := v_payment.invoice_id;
  perform public.undo_invoice_payment_safe(v_payment.id);
  v_new_payment := public.record_invoice_payment(v_invoice_id,p_amount,p_paid_on,null,p_reference);
  return v_new_payment;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_and_issue_service_invoice(p_company_id uuid, p_customer_name text, p_customer_email text, p_customer_country text, p_customer_vat_number text, p_customer_address jsonb, p_issue_date date, p_service_date date, p_due_date date, p_vat_treatment text, p_lines jsonb, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_company public.companies%rowtype;
  v_contact_id uuid;
  v_invoice_id uuid;
  v_invoice_number text;
  v_seq bigint;
  v_year integer;
  v_line jsonb;
  v_line_no integer:=0;
  v_desc text;
  v_qty numeric(18,4);
  v_unit numeric(18,4);
  v_rate numeric(5,2);
  v_net numeric(18,2);
  v_vat numeric(18,2);
  v_gross numeric(18,2);
  v_subtotal numeric(18,2):=0;
  v_vat_total numeric(18,2):=0;
  v_total numeric(18,2):=0;
  v_receivable public.company_accounts%rowtype;
  v_revenue public.company_accounts%rowtype;
  v_vat_account public.company_accounts%rowtype;
  v_period_id uuid; v_period_start date; v_period_end date; v_period_year integer;
  v_entry_id uuid; v_entry_number bigint;
  v_customer_snapshot jsonb; v_issuer_snapshot jsonb;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select * into v_company from public.companies where id=p_company_id;
  if not found then raise exception 'Company not found'; end if;
  if not app_private.can_bookkeep_org(v_company.organization_id) then raise exception 'You do not have permission to issue invoices for this company'; end if;
  if coalesce(v_company.registered_address,'{}'::jsonb)='{}'::jsonb then raise exception 'Complete the registered office address before issuing an invoice'; end if;
  if v_company.vat_registered and nullif(trim(v_company.vat_number),'') is null then raise exception 'Complete the company VAT number before issuing a VAT invoice'; end if;
  if nullif(trim(p_customer_name),'') is null then raise exception 'Customer name is required'; end if;
  if nullif(trim(p_customer_country),'') is null or length(trim(p_customer_country))<>2 then raise exception 'Customer country code is required'; end if;
  if coalesce(p_customer_address,'{}'::jsonb)='{}'::jsonb then raise exception 'Customer address is required'; end if;
  if p_issue_date is null or p_service_date is null or p_due_date is null then raise exception 'Invoice, service and due dates are required'; end if;
  if p_due_date<p_issue_date then raise exception 'Due date cannot be before the invoice date'; end if;
  if p_vat_treatment not in ('domestic','eu_b2b_reverse_charge') then raise exception 'Unsupported VAT treatment'; end if;
  if p_vat_treatment='eu_b2b_reverse_charge' then
    if upper(trim(p_customer_country))='LU' then raise exception 'EU reverse charge cannot be used for a Luxembourg customer'; end if;
    if nullif(trim(p_customer_vat_number),'') is null then raise exception 'Customer VAT number is required for EU B2B reverse charge'; end if;
  end if;
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'At least one invoice line is required'; end if;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_line_no:=v_line_no+1;
    v_desc:=trim(coalesce(v_line->>'description',''));
    v_qty:=coalesce((v_line->>'quantity')::numeric,0);
    v_unit:=coalesce((v_line->>'unit_price')::numeric,0);
    v_rate:=coalesce((v_line->>'vat_rate')::numeric,0);
    if v_desc='' then raise exception 'Every invoice line needs a description'; end if;
    if v_qty<=0 or v_unit<0 then raise exception 'Invoice quantities and prices are invalid'; end if;
    if p_vat_treatment='eu_b2b_reverse_charge' then v_rate:=0; end if;
    if v_rate not in (0,3,8,14,17) then raise exception 'Unsupported Luxembourg VAT rate %',v_rate; end if;
    if p_vat_treatment='domestic' and not v_company.vat_registered and v_rate<>0 then raise exception 'A non-VAT-registered company cannot charge VAT'; end if;
    v_net:=round(v_qty*v_unit,2); v_vat:=round(v_net*v_rate/100,2); v_gross:=v_net+v_vat;
    v_subtotal:=v_subtotal+v_net; v_vat_total:=v_vat_total+v_vat; v_total:=v_total+v_gross;
  end loop;

  select id into v_contact_id from public.contacts
   where company_id=v_company.id and (
     (nullif(trim(p_customer_vat_number),'') is not null and upper(coalesce(vat_number,''))=upper(trim(p_customer_vat_number)))
     or (nullif(trim(p_customer_email),'') is not null and lower(coalesce(email,''))=lower(trim(p_customer_email)))
   ) order by created_at asc limit 1;
  if v_contact_id is null then
    insert into public.contacts(organization_id,company_id,type,display_name,legal_name,country_code,vat_number,email,address)
    values(v_company.organization_id,v_company.id,'customer',trim(p_customer_name),trim(p_customer_name),upper(trim(p_customer_country)),nullif(trim(p_customer_vat_number),''),nullif(trim(p_customer_email),''),coalesce(p_customer_address,'{}'::jsonb)) returning id into v_contact_id;
  else
    update public.contacts set display_name=trim(p_customer_name),legal_name=trim(p_customer_name),country_code=upper(trim(p_customer_country)),vat_number=nullif(trim(p_customer_vat_number),''),email=nullif(trim(p_customer_email),''),address=coalesce(p_customer_address,'{}'::jsonb),updated_at=now() where id=v_contact_id;
  end if;

  v_issuer_snapshot:=jsonb_build_object('legal_name',v_company.legal_name,'legal_form',v_company.legal_form,'rcs_number',v_company.rcs_number,'vat_number',v_company.vat_number,'business_permit_number',v_company.business_permit_number,'registered_address',v_company.registered_address);
  v_customer_snapshot:=jsonb_build_object('name',trim(p_customer_name),'email',nullif(trim(p_customer_email),''),'country_code',upper(trim(p_customer_country)),'vat_number',nullif(trim(p_customer_vat_number),''),'address',coalesce(p_customer_address,'{}'::jsonb));

  insert into public.sales_invoices(organization_id,company_id,contact_id,status,payment_status,issue_date,service_date,due_date,currency,vat_treatment,subtotal,vat_total,total,issuer_snapshot,customer_snapshot,notes,created_by)
  values(v_company.organization_id,v_company.id,v_contact_id,'draft','unpaid',p_issue_date,p_service_date,p_due_date,v_company.base_currency,p_vat_treatment,v_subtotal,v_vat_total,v_total,v_issuer_snapshot,v_customer_snapshot,nullif(trim(p_notes),''),v_uid) returning id into v_invoice_id;

  v_line_no:=0;
  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_line_no:=v_line_no+1; v_desc:=trim(v_line->>'description'); v_qty:=(v_line->>'quantity')::numeric; v_unit:=(v_line->>'unit_price')::numeric; v_rate:=coalesce((v_line->>'vat_rate')::numeric,0); if p_vat_treatment='eu_b2b_reverse_charge' then v_rate:=0; end if;
    v_net:=round(v_qty*v_unit,2); v_vat:=round(v_net*v_rate/100,2); v_gross:=v_net+v_vat;
    insert into public.sales_invoice_lines(organization_id,company_id,invoice_id,line_number,description,quantity,unit_price,vat_rate,net_amount,vat_amount,gross_amount,revenue_account_code)
    values(v_company.organization_id,v_company.id,v_invoice_id,v_line_no,v_desc,v_qty,v_unit,v_rate,v_net,v_vat,v_gross,'7033');
  end loop;

  v_year:=extract(year from p_issue_date)::integer;
  insert into public.invoice_sequences(company_id,fiscal_year,last_number) values(v_company.id,v_year,1)
  on conflict(company_id,fiscal_year) do update set last_number=public.invoice_sequences.last_number+1
  returning last_number into v_seq;
  v_invoice_number:='INV-'||v_year::text||'-'||lpad(v_seq::text,4,'0');

  select * into v_receivable from public.company_accounts where company_id=v_company.id and code='4011' and is_active=true;
  select * into v_revenue from public.company_accounts where company_id=v_company.id and code='7033' and is_active=true;
  if v_receivable.id is null or v_revenue.id is null then raise exception 'Required customer or revenue ledger account is missing'; end if;
  if v_vat_total>0 then select * into v_vat_account from public.company_accounts where company_id=v_company.id and code='461411' and is_active=true; if v_vat_account.id is null then raise exception 'Output VAT ledger account is missing'; end if; end if;

  v_period_year:=extract(year from p_service_date)::integer;
  if extract(month from p_service_date)::integer<v_company.fiscal_year_start_month then v_period_year:=v_period_year-1; end if;
  v_period_start:=make_date(v_period_year,v_company.fiscal_year_start_month,1); v_period_end:=(v_period_start+interval '1 year - 1 day')::date;
  select id into v_period_id from public.accounting_periods where company_id=v_company.id and starts_on=v_period_start and ends_on=v_period_end and status in ('open','soft_closed') limit 1;
  if v_period_id is null then
    insert into public.accounting_periods(organization_id,company_id,starts_on,ends_on,status) values(v_company.organization_id,v_company.id,v_period_start,v_period_end,'open') on conflict(company_id,starts_on,ends_on) do nothing;
    select id into v_period_id from public.accounting_periods where company_id=v_company.id and starts_on=v_period_start and ends_on=v_period_end and status in ('open','soft_closed') limit 1;
  end if;
  if v_period_id is null then raise exception 'The accounting period is closed or locked'; end if;

  perform pg_advisory_xact_lock(hashtextextended(v_company.id::text,0));
  select coalesce(max(entry_number),0)+1 into v_entry_number from public.journal_entries where company_id=v_company.id;
  insert into public.journal_entries(organization_id,company_id,accounting_period_id,entry_number,entry_date,document_date,description,source_type,source_id,status,created_by)
  values(v_company.organization_id,v_company.id,v_period_id,v_entry_number,p_service_date,p_issue_date,'Invoice '||v_invoice_number||' — '||trim(p_customer_name),'invoice',v_invoice_id,'draft',v_uid) returning id into v_entry_id;
  insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,contact_id,description,debit,credit,currency,exchange_rate)
  values(v_company.organization_id,v_entry_id,v_receivable.id,v_contact_id,'Customer receivable '||v_invoice_number,v_total,0,v_company.base_currency,1);
  insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,contact_id,description,debit,credit,currency,exchange_rate)
  values(v_company.organization_id,v_entry_id,v_revenue.id,v_contact_id,'Service revenue '||v_invoice_number,0,v_subtotal,v_company.base_currency,1);
  if v_vat_total>0 then
    insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,contact_id,description,debit,credit,currency,exchange_rate,vat_code,vat_amount)
    values(v_company.organization_id,v_entry_id,v_vat_account.id,v_contact_id,'Output VAT '||v_invoice_number,0,v_vat_total,v_company.base_currency,1,'OUTPUT',v_vat_total);
  end if;
  perform public.post_journal_entry(v_entry_id);

  update public.sales_invoices set invoice_number=v_invoice_number,status='issued',journal_entry_id=v_entry_id,issued_at=now(),updated_at=now() where id=v_invoice_id;
  return v_invoice_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_company_workspace(p_legal_name text, p_slug text, p_legal_form text, p_rcs_number text DEFAULT NULL::text, p_vat_number text DEFAULT NULL::text, p_municipality text DEFAULT NULL::text, p_vat_registered boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_org_id uuid;
  v_company_id uuid;
  v_year integer := extract(year from current_date)::integer;
begin
  if v_uid is null then
    raise exception 'Authentication required';
  end if;

  if nullif(trim(p_legal_name), '') is null then
    raise exception 'Legal company name is required';
  end if;

  if nullif(trim(p_slug), '') is null then
    raise exception 'Workspace slug is required';
  end if;

  insert into public.organizations (name, slug, owner_id)
  values (trim(p_legal_name), lower(trim(p_slug)), v_uid)
  returning id into v_org_id;

  insert into public.companies (
    organization_id,
    legal_name,
    legal_form,
    rcs_number,
    vat_number,
    municipality,
    vat_registered,
    vat_filing_frequency,
    base_currency
  )
  values (
    v_org_id,
    trim(p_legal_name),
    p_legal_form,
    nullif(trim(p_rcs_number), ''),
    nullif(trim(p_vat_number), ''),
    nullif(trim(p_municipality), ''),
    coalesce(p_vat_registered, false),
    case when coalesce(p_vat_registered, false) then 'annual' else null end,
    'EUR'
  )
  returning id into v_company_id;

  insert into public.company_accounts (
    organization_id, company_id, pcn_account_id, code, label, account_type, is_active
  )
  select
    v_org_id, v_company_id, p.id, p.code, coalesce(p.label_en, p.label_fr), p.account_type, true
  from public.pcn_accounts p
  where p.source_version = 'PCN2020'
    and p.is_active = true
  on conflict (company_id, code) do nothing;

  insert into public.accounting_periods (
    organization_id, company_id, starts_on, ends_on, status
  )
  values (
    v_org_id,
    v_company_id,
    make_date(v_year, 1, 1),
    make_date(v_year, 12, 31),
    'open'
  )
  on conflict (company_id, starts_on, ends_on) do nothing;

  return v_company_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_company_workspace_v2(p_legal_name text, p_slug text, p_legal_form text, p_rcs_number text DEFAULT NULL::text, p_vat_number text DEFAULT NULL::text, p_municipality text DEFAULT NULL::text, p_vat_registered boolean DEFAULT true, p_business_permit_number text DEFAULT NULL::text, p_registered_address jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_org_id uuid;
  v_company_id uuid;
  v_year integer := extract(year from current_date)::integer;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if nullif(btrim(p_legal_name), '') is null then raise exception 'Legal company name is required'; end if;
  if nullif(btrim(p_slug), '') is null then raise exception 'Workspace slug is required'; end if;
  if p_legal_form not in ('SARL-S', 'SARL', 'SA', 'SAS', 'SCA', 'OTHER') then
    raise exception 'Choose a valid incorporated company legal form';
  end if;

  insert into public.organizations(name, slug, owner_id)
  values (btrim(p_legal_name), lower(btrim(p_slug)), v_uid)
  returning id into v_org_id;

  insert into public.companies(
    organization_id, legal_name, legal_form, entity_kind, rcs_number, vat_number,
    municipality, vat_registered, vat_filing_frequency, base_currency,
    business_permit_number, registered_address
  ) values (
    v_org_id, btrim(p_legal_name), p_legal_form, 'company', nullif(btrim(p_rcs_number), ''),
    nullif(btrim(p_vat_number), ''), nullif(btrim(p_municipality), ''), coalesce(p_vat_registered, false),
    case when coalesce(p_vat_registered, false) then 'annual' else null end, 'EUR',
    nullif(btrim(p_business_permit_number), ''), coalesce(p_registered_address, '{}'::jsonb)
  ) returning id into v_company_id;

  insert into public.company_accounts(organization_id, company_id, pcn_account_id, code, label, account_type, is_active)
  select v_org_id, v_company_id, p.id, p.code, coalesce(p.label_en, p.label_fr), p.account_type, true
  from public.pcn_accounts p
  where p.source_version = 'PCN2020' and p.is_active = true
  on conflict (company_id, code) do nothing;

  insert into public.accounting_periods(organization_id, company_id, starts_on, ends_on, status)
  values (v_org_id, v_company_id, make_date(v_year, 1, 1), make_date(v_year, 12, 31), 'open')
  on conflict (company_id, starts_on, ends_on) do nothing;
  return v_company_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_independent_workspace_v1(p_personal_legal_name text, p_activity_name text, p_slug text, p_activity_description text, p_activity_category text, p_activity_start_date date, p_accounting_start_date date, p_location text DEFAULT 'Luxembourg'::text, p_vat_registered boolean DEFAULT false, p_vat_number text DEFAULT NULL::text, p_vat_filing_frequency text DEFAULT NULL::text, p_rcs_registered boolean DEFAULT false, p_rcs_number text DEFAULT NULL::text, p_business_permit_held boolean DEFAULT false, p_business_permit_number text DEFAULT NULL::text, p_opening_cash_amount numeric DEFAULT 0, p_tax_year smallint DEFAULT (EXTRACT(year FROM CURRENT_DATE))::smallint, p_residency_status text DEFAULT 'resident'::text, p_civil_status text DEFAULT 'single'::text, p_civil_status_event_date date DEFAULT NULL::date, p_qualifying_children_count smallint DEFAULT 0, p_age_64_at_year_start boolean DEFAULT false, p_taxation_mode text DEFAULT 'not_applicable'::text, p_partnership_full_year_conditions_met boolean DEFAULT false, p_legally_recognized_separation boolean DEFAULT false, p_transitional_class_2_used_in_prior_five_years boolean DEFAULT false, p_derived_tax_class text DEFAULT '1'::text, p_affiliation_type text DEFAULT 'principal'::text, p_estimated_annual_professional_income numeric DEFAULT 0, p_aaa_factor numeric DEFAULT 1.0000, p_mde_membership text DEFAULT 'not_affiliated'::text, p_mde_class smallint DEFAULT NULL::smallint)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_org_id uuid;
  v_company_id uuid;
  v_display_name text;
  v_period_start date;
  v_period_end date;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if nullif(btrim(p_personal_legal_name), '') is null then raise exception 'Personal legal name is required'; end if;
  if nullif(btrim(p_slug), '') is null then raise exception 'Workspace slug is required'; end if;
  if p_activity_category not in ('liberal_profession', 'commercial', 'craft', 'consultant_freelancer', 'other') then raise exception 'Invalid activity category'; end if;
  if p_vat_filing_frequency is not null and p_vat_filing_frequency not in ('annual', 'quarterly', 'monthly') then raise exception 'Invalid VAT filing frequency'; end if;
  if p_affiliation_type not in ('principal', 'secondary') then raise exception 'Invalid independent affiliation type'; end if;
  if p_residency_status not in ('resident', 'non_resident') then raise exception 'Invalid residency status'; end if;
  if p_civil_status not in ('single', 'married', 'registered_partnership', 'divorced', 'separated', 'widowed') then raise exception 'Invalid civil status'; end if;
  if p_taxation_mode not in ('joint', 'individual', 'individual_reallocation', 'not_applicable', 'needs_confirmation') then raise exception 'Invalid taxation mode'; end if;
  if p_derived_tax_class not in ('1', '1a', '2', 'needs_confirmation') then raise exception 'Invalid derived tax class'; end if;
  if p_mde_membership not in ('not_affiliated', 'affiliated') then raise exception 'Invalid MDE membership'; end if;
  if p_mde_membership = 'affiliated' and not coalesce(p_mde_class between 1 and 4, false) then raise exception 'Confirm the MDE class'; end if;
  if p_mde_membership = 'not_affiliated' and p_mde_class is not null then raise exception 'MDE class requires membership'; end if;
  if p_activity_start_date is null or p_accounting_start_date is null then raise exception 'Activity and accounting start dates are required'; end if;
  if coalesce(p_opening_cash_amount, 0) < 0 or coalesce(p_estimated_annual_professional_income, 0) < 0 then raise exception 'Amounts cannot be negative'; end if;

  v_display_name := coalesce(nullif(btrim(p_activity_name), ''), btrim(p_personal_legal_name));
  v_period_start := make_date(p_tax_year, 1, 1);
  v_period_end := make_date(p_tax_year, 12, 31);

  insert into public.organizations(name, slug, owner_id)
  values (v_display_name, lower(btrim(p_slug)), v_uid)
  returning id into v_org_id;

  insert into public.companies(
    organization_id, legal_name, trading_name, legal_form, entity_kind, rcs_number,
    vat_number, business_permit_number, municipality, activity, fiscal_year_start_month,
    base_currency, vat_registered, vat_filing_frequency, registered_address
  ) values (
    v_org_id, btrim(p_personal_legal_name), nullif(btrim(p_activity_name), ''), 'INDEPENDENT', 'independent',
    case when p_rcs_registered then nullif(btrim(p_rcs_number), '') else null end,
    case when p_vat_registered then nullif(btrim(p_vat_number), '') else null end,
    case when p_business_permit_held then nullif(btrim(p_business_permit_number), '') else null end,
    nullif(btrim(p_location), ''), nullif(btrim(p_activity_description), ''), 1, 'EUR',
    coalesce(p_vat_registered, false), case when p_vat_registered then coalesce(p_vat_filing_frequency, 'annual') else null end,
    jsonb_build_object('city', coalesce(nullif(btrim(p_location), ''), 'Luxembourg'), 'country_code', 'LU')
  ) returning id into v_company_id;

  insert into public.independent_activity_profiles(
    company_id, user_id, personal_legal_name, activity_name, activity_category,
    activity_start_date, accounting_start_date, location, rcs_registered,
    business_permit_held, opening_cash_amount
  ) values (
    v_company_id, v_uid, btrim(p_personal_legal_name), nullif(btrim(p_activity_name), ''), p_activity_category,
    p_activity_start_date, p_accounting_start_date, coalesce(nullif(btrim(p_location), ''), 'Luxembourg'),
    coalesce(p_rcs_registered, false), coalesce(p_business_permit_held, false), coalesce(p_opening_cash_amount, 0)
  );

  insert into public.company_accounts(organization_id, company_id, pcn_account_id, code, label, account_type, is_active)
  select v_org_id, v_company_id, p.id, p.code, coalesce(p.label_en, p.label_fr), p.account_type, true
  from public.pcn_accounts p
  where p.source_version = 'PCN2020' and p.is_active = true
  on conflict (company_id, code) do nothing;

  insert into public.accounting_periods(organization_id, company_id, starts_on, ends_on, status)
  values (v_org_id, v_company_id, v_period_start, v_period_end, 'open')
  on conflict (company_id, starts_on, ends_on) do nothing;

  insert into public.compliance_obligations(
    organization_id, company_id, authority, obligation_type, period_label,
    due_date, status, rule_key, rule_version, metadata
  ) values (
    v_org_id, v_company_id, 'CCSS', 'Initial self-employed affiliation',
    extract(year from p_activity_start_date)::text, p_activity_start_date + 8,
    case when p_activity_start_date + 8 < current_date then 'overdue' else 'upcoming' end,
    'ccss_initial_affiliation', '2026.1',
    jsonb_build_object('activity_start_date', p_activity_start_date, 'source_authority', 'CCSS', 'semantic_state', 'derived_deadline')
  ) on conflict (company_id, rule_key, period_label) where rule_key is not null do nothing;

  insert into public.personal_fiscal_profiles(
    user_id, tax_year, residency_status, civil_status, civil_status_event_date, qualifying_children_count,
    age_64_at_year_start, taxation_mode, partnership_full_year_conditions_met,
    legally_recognized_separation, transitional_class_2_used_in_prior_five_years,
    derived_tax_class, derivation_version, last_confirmed_at
  ) values (
    v_uid, p_tax_year, p_residency_status, p_civil_status, p_civil_status_event_date, p_qualifying_children_count,
    p_age_64_at_year_start, p_taxation_mode, p_partnership_full_year_conditions_met,
    p_legally_recognized_separation, p_transitional_class_2_used_in_prior_five_years,
    p_derived_tax_class, 'lu-resident-2026-v1', now()
  ) on conflict (user_id, tax_year) do nothing;

  insert into public.ccss_profiles(
    user_id, tax_year, affiliation_type, activity_legal_form, affiliation_start_date,
    estimated_annual_professional_income, income_status, income_source, aaa_factor,
    mde_membership, mde_class, pension_reduction_status, insignificant_income_exemption_status,
    assisting_spouse_enabled, assisting_spouse_qualifying_relationship, assisting_spouse_main_activity,
    last_confirmed_at
  ) values (
    v_uid, p_tax_year, p_affiliation_type, 'own_name', p_activity_start_date,
    p_estimated_annual_professional_income, 'user_confirmed', 'manual', p_aaa_factor,
    p_mde_membership, case when p_mde_membership = 'affiliated' then p_mde_class else null end,
    'not_requested', 'not_requested', false, false, false, now()
  ) on conflict (user_id, tax_year) do nothing;

  return v_company_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_organization_invitation(p_organization_id uuid, p_email text, p_role text)
 RETURNS TABLE(id uuid, token uuid, email text, role text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_email text := lower(btrim(coalesce(p_email,'')));
  v_id uuid;
  v_token uuid;
  v_expires timestamptz;
  v_auth_flow text;
begin
  if not app_private.can_manage_org(p_organization_id) then
    raise exception 'Not authorized to manage this organization';
  end if;
  if v_email = '' or position('@' in v_email) < 2 then
    raise exception 'Enter a valid email address';
  end if;
  if p_role not in ('admin','accountant','bookkeeper','viewer') then
    raise exception 'Invalid invitation role';
  end if;
  if exists (
    select 1
    from public.organization_members om
    join auth.users u on u.id=om.user_id
    where om.organization_id=p_organization_id and lower(u.email)=v_email
  ) then
    raise exception 'This person is already a member of the organization';
  end if;

  select case
    when exists(
      select 1 from auth.users u
      where lower(u.email)=v_email
        and (
          u.last_sign_in_at is not null
          or exists(select 1 from public.organization_members m where m.user_id=u.id)
        )
    ) then 'existing_user'
    else 'new_user'
  end into v_auth_flow;

  update public.organization_invitations oi
     set status='revoked',revoked_at=now()
   where oi.organization_id=p_organization_id
     and lower(oi.email)=v_email
     and oi.status='pending';

  insert into public.organization_invitations(organization_id,email,role,invited_by,auth_flow)
  values(p_organization_id,v_email,p_role,auth.uid(),v_auth_flow)
  returning organization_invitations.id,organization_invitations.token,organization_invitations.expires_at
    into v_id,v_token,v_expires;

  return query select v_id,v_token,v_email,p_role,v_expires;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_source_transaction_from_document(p_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_doc public.documents%rowtype;
  v_existing_id uuid;
  v_transaction_id uuid;
  v_link_id uuid;
  v_kind text;
  v_direction text;
  v_currency text;
  v_counterparty text;
  v_counterparty_country text;
  v_description text;
  v_treatment text;
  v_date date;
  v_total numeric(18,2);
  v_net numeric(18,2);
  v_vat numeric(18,2);
  v_rate numeric(5,2);
  v_line_count integer := 0;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;

  select * into v_doc
  from public.documents
  where id=p_document_id
  for update;

  if not found then raise exception 'Document not found'; end if;
  if not app_private.can_bookkeep_org(v_doc.organization_id) then raise exception 'Permission denied'; end if;

  select id into v_existing_id
  from public.source_transactions
  where company_id=v_doc.company_id
    and source_type='document'
    and source_id=v_doc.id
  order by created_at asc
  limit 1;

  if v_existing_id is not null then
    return jsonb_build_object('transaction_id',v_existing_id,'created',false,'matched_existing',false,'already_created',true);
  end if;

  if v_doc.extracted_data is null or v_doc.extraction_status not in ('needs_review','complete') then
    raise exception 'Analyze the document before creating a transaction';
  end if;

  if jsonb_typeof(v_doc.extracted_data->'type_safeguard') = 'object'
     and coalesce((v_doc.extracted_data->'type_safeguard'->>'resolved')::boolean,false) = false then
    raise exception 'Confirm the document type before creating a transaction';
  end if;

  v_kind:=nullif(trim(v_doc.extracted_data->>'document_kind'),'');
  begin
    if jsonb_typeof(v_doc.extracted_data->'line_items')='array' then
      v_line_count:=jsonb_array_length(v_doc.extracted_data->'line_items');
    end if;
  exception when others then
    v_line_count:=0;
  end;

  -- The category chosen by the user in Transactions is authoritative.
  -- AI classification enriches the document but must not block a receipt/invoice intake.
  if v_doc.type not in ('receipt','purchase_invoice','sales_invoice') then
    if v_kind in ('receipt','purchase_invoice','sales_invoice') then
      null;
    elsif v_kind='bank_statement'
      and nullif(trim(v_doc.extracted_data->>'transaction_counterparty'),'') is not null
      and v_line_count=1 then
      null;
    else
      raise exception 'This document does not represent a single transaction that Zuelen can prepare automatically';
    end if;
  end if;

  begin v_total:=nullif(v_doc.extracted_data->>'total','')::numeric; exception when others then v_total:=null; end;
  if v_total is null or v_total<=0 then raise exception 'The document amount could not be read. Review the document before creating a transaction'; end if;
  v_total:=round(v_total,2);

  begin
    v_date:=coalesce(
      nullif(v_doc.extracted_data->>'service_date','')::date,
      nullif(v_doc.extracted_data->>'document_date','')::date
    );
  exception when others then
    v_date:=null;
  end;
  if v_date is null then raise exception 'The transaction date could not be read. Review the document before creating a transaction'; end if;

  v_currency:=upper(coalesce(nullif(trim(v_doc.extracted_data->>'currency'),''),'EUR'));
  if v_currency !~ '^[A-Z]{3}$' then v_currency:='EUR'; end if;

  v_direction:=nullif(trim(v_doc.extracted_data->>'transaction_direction'),'');
  if v_direction is null or v_direction not in ('income','expense') then
    v_direction:=case when v_kind='sales_invoice' or v_doc.type='sales_invoice' then 'income' else 'expense' end;
  end if;

  select string_agg(nullif(trim(item->>'description'),''),' · ')
  into v_description
  from jsonb_array_elements(coalesce(v_doc.extracted_data->'line_items','[]'::jsonb)) item
  where nullif(trim(item->>'description'),'') is not null;

  v_counterparty:=nullif(trim(v_doc.extracted_data->>'transaction_counterparty'),'');
  if v_counterparty is null then
    v_counterparty:=case
      when v_kind='sales_invoice' or v_doc.type='sales_invoice' then nullif(trim(v_doc.extracted_data->>'customer_name'),'')
      else nullif(trim(v_doc.extracted_data->>'issuer_name'),'')
    end;
  end if;

  v_counterparty_country:=case
    when v_kind='sales_invoice' or v_doc.type='sales_invoice' then nullif(upper(trim(v_doc.extracted_data->>'customer_country')),'')
    else nullif(upper(trim(v_doc.extracted_data->>'issuer_country')),'')
  end;

  if coalesce(v_doc.extracted_data->>'notes','') ilike '%transaction statement%'
     and v_description is not null then
    v_counterparty:=coalesce(nullif(trim(v_doc.extracted_data->>'transaction_counterparty'),''),split_part(v_description,' · ',1));
    v_counterparty_country:=null;
  end if;

  if v_counterparty_country is not null and v_counterparty_country !~ '^[A-Z]{2}$' then
    v_counterparty_country:=null;
  end if;

  begin v_net:=nullif(v_doc.extracted_data->>'subtotal','')::numeric; exception when others then v_net:=null; end;
  begin v_vat:=nullif(v_doc.extracted_data->>'vat_amount','')::numeric; exception when others then v_vat:=null; end;
  begin v_rate:=nullif(v_doc.extracted_data->>'vat_rate','')::numeric; exception when others then v_rate:=null; end;

  if v_rate is not null and v_rate not in (0,3,8,14,17) then v_rate:=null; end if;
  if v_net is not null then v_net:=round(v_net,2); end if;
  if v_vat is not null then v_vat:=round(v_vat,2); end if;
  if v_net is not null and v_vat is not null and round(v_net+v_vat,2)<>v_total then
    v_net:=null; v_vat:=null; v_rate:=null;
  end if;

  v_treatment:=coalesce(nullif(trim(v_doc.extracted_data->>'suggested_vat_treatment'),''),'unknown');
  if v_treatment not in ('domestic','eu_b2b_reverse_charge','eu_acquisition','non_eu','exempt_or_zero','outside_scope','unknown') then
    v_treatment:='unknown';
  end if;

  select l.source_transaction_id into v_existing_id
  from public.document_transaction_links l
  join public.source_transactions st on st.id=l.source_transaction_id
  where l.document_id=v_doc.id
    and l.status in ('suggested','confirmed')
    and l.source_transaction_id is not null
    and upper(st.currency)=v_currency
    and abs(st.amount_gross-v_total)<=0.02
    and coalesce(l.match_score,0)>=0.83
  order by case when l.status='confirmed' then 0 else 1 end,l.match_score desc,l.created_at asc
  limit 1;

  if v_existing_id is not null then
    return jsonb_build_object('transaction_id',v_existing_id,'created',false,'matched_existing',true,'already_created',false);
  end if;

  perform public.assert_usage_available(v_doc.organization_id,'transactions',1);

  insert into public.source_transactions(
    organization_id,company_id,occurred_on,direction,amount_gross,amount_net,vat_amount,currency,
    counterparty_name,description,source_type,source_id,classification_status,created_by,vat_rate,
    vat_treatment,counterparty_country
  )
  values(
    v_doc.organization_id,v_doc.company_id,v_date,v_direction,v_total,v_net,v_vat,v_currency,
    v_counterparty,v_description,'document',v_doc.id,'review',v_uid,v_rate,v_treatment,v_counterparty_country
  )
  returning id into v_transaction_id;

  perform public.apply_source_transaction_suggestion(v_transaction_id);

  insert into public.document_transaction_links(
    organization_id,company_id,document_id,source_transaction_id,match_score,status,match_reason,created_by
  )
  values(
    v_doc.organization_id,v_doc.company_id,v_doc.id,v_transaction_id,1,'suggested',
    'Transaction created from this document''s extracted facts.',v_uid
  )
  returning id into v_link_id;

  perform public.confirm_document_match(v_link_id);

  return jsonb_build_object('transaction_id',v_transaction_id,'created',true,'matched_existing',false,'already_created',false);
end
$function$
;

CREATE OR REPLACE FUNCTION public.create_tax_event_from_document(p_document_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v_doc public.documents%rowtype; v_id uuid; v_due date; v_year integer; v_amount numeric; v_type text; v_ref text;
begin
 select * into v_doc from public.documents where id=p_document_id;
 if not found then raise exception 'Document not found'; end if;
 if not app_private.can_account_org(v_doc.organization_id) then raise exception 'Permission denied'; end if;
 if coalesce(v_doc.extracted_data->>'document_kind','')<>'tax_notice' and v_doc.type<>'tax_notice' then raise exception 'Document is not identified as a tax notice'; end if;
 begin v_due:=nullif(v_doc.extracted_data->>'due_date','')::date; exception when others then v_due:=null; end;
 begin v_amount:=nullif(v_doc.extracted_data->>'total','')::numeric; exception when others then v_amount:=null; end;
 begin v_year:=coalesce(nullif(v_doc.extracted_data->>'tax_year','')::integer,extract(year from coalesce(nullif(v_doc.extracted_data->>'document_date','')::date,current_date))::integer); exception when others then v_year:=extract(year from current_date)::integer; end;
 v_type:=coalesce(nullif(v_doc.extracted_data->>'tax_type',''),nullif(v_doc.extracted_data->>'suggested_account_category',''),'tax_notice');
 v_ref:=nullif(v_doc.extracted_data->>'invoice_number','');
 insert into public.tax_events(organization_id,company_id,source_document_id,authority,tax_type,tax_year,amount,due_date,reference,status,metadata,created_by) values(v_doc.organization_id,v_doc.company_id,v_doc.id,'ACD',v_type,v_year,v_amount,v_due,v_ref,'open',coalesce(v_doc.extracted_data,'{}'::jsonb),auth.uid()) returning id into v_id;
 if v_due is not null then insert into public.compliance_obligations(organization_id,company_id,authority,obligation_type,period_label,due_date,amount,status,source_document_id,metadata) values(v_doc.organization_id,v_doc.company_id,'ACD',v_type,coalesce(v_year::text,'Tax notice'),v_due,v_amount,'upcoming',v_doc.id,jsonb_build_object('tax_event_id',v_id,'reference',v_ref)); end if;
 return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.current_user_requires_mfa()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from auth.mfa_factors factor
    where factor.user_id = (select auth.uid())
      and factor.status = 'verified'
  )
  and coalesce((select auth.jwt() ->> 'aal'), 'aal1') <> 'aal2';
$function$
;

CREATE OR REPLACE FUNCTION public.delete_source_transaction_safe(p_source_transaction_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_tx public.source_transactions%rowtype;
  v_reversal uuid;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select * into v_tx from public.source_transactions where id=p_source_transaction_id for update;
  if not found then raise exception 'Transaction not found'; end if;
  if not app_private.can_bookkeep_org(v_tx.organization_id) then raise exception 'You do not have permission to delete this transaction'; end if;

  if v_tx.classification_status='posted' and v_tx.posted_journal_entry_id is not null then
    v_reversal:=public.reverse_posted_journal_entry(v_tx.posted_journal_entry_id,'Transaction deleted');
  end if;

  delete from public.source_transactions where id=v_tx.id;

  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_tx.organization_id,v_tx.company_id,v_uid,'source_transaction.deleted','source_transaction',v_tx.id,jsonb_build_object('posted',v_tx.posted_journal_entry_id is not null,'reversal_entry_id',v_reversal,'snapshot',to_jsonb(v_tx)));
  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_billing_snapshot(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_sub public.organization_subscriptions%rowtype;
  v_start timestamptz;
  v_end timestamptz;
  v_transactions integer;
  v_documents integer;
  v_invoices integer;
  v_bank_imports integer;
  v_billable_seats integer;
begin
  if not app_private.is_org_member(p_organization_id) then
    raise exception 'Not authorized to view this organization';
  end if;
  select * into v_sub from public.organization_subscriptions s where s.organization_id=p_organization_id;
  if v_sub.organization_id is null then
    insert into public.organization_subscriptions(organization_id,plan,status,billing_source,billing_anchor)
    select o.id,'basic','active','stripe',o.created_at from public.organizations o where o.id=p_organization_id
    on conflict (organization_id) do nothing;
    select * into v_sub from public.organization_subscriptions s where s.organization_id=p_organization_id;
  end if;
  select b.period_start,b.period_end into v_start,v_end from app_private.subscription_period_bounds(p_organization_id) b;
  v_transactions:=app_private.usage_count(p_organization_id,'transactions');
  v_documents:=app_private.usage_count(p_organization_id,'documents');
  v_invoices:=app_private.usage_count(p_organization_id,'invoices');
  v_bank_imports:=app_private.usage_count(p_organization_id,'bank_imports');
  v_billable_seats:=app_private.billable_team_seats(p_organization_id);
  return jsonb_build_object(
    'plan',v_sub.plan,
    'status',v_sub.status,
    'billing_source',v_sub.billing_source,
    'billing_interval',v_sub.billing_interval,
    'period_start',v_start,
    'period_end',v_end,
    'cancel_at_period_end',v_sub.cancel_at_period_end,
    'additional_seats',v_sub.additional_seats,
    'billable_seats',v_billable_seats,
    'stripe_customer_id',v_sub.stripe_customer_id,
    'stripe_plan_subscription_id',v_sub.stripe_plan_subscription_id,
    'stripe_seat_subscription_id',v_sub.stripe_seat_subscription_id,
    'usage',jsonb_build_object(
      'transactions',jsonb_build_object('used',v_transactions,'limit',case when v_sub.plan='premium' then null else 15 end),
      'documents',jsonb_build_object('used',v_documents,'limit',case when v_sub.plan='premium' then null else 3 end),
      'invoices',jsonb_build_object('used',v_invoices,'limit',case when v_sub.plan='premium' then null else 3 end),
      'bank_imports',jsonb_build_object('used',v_bank_imports,'limit',case when v_sub.plan='premium' then null else 1 end)
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_organization_invitation(p_token uuid)
 RETURNS TABLE(id uuid, organization_id uuid, organization_name text, email text, role text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_auth_email text := lower(coalesce(auth.jwt()->>'email',''));
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  return query
    select oi.id,oi.organization_id,o.name::text,oi.email::text,oi.role::text,oi.expires_at
      from public.organization_invitations oi
      join public.organizations o on o.id=oi.organization_id
     where oi.token=p_token
       and oi.status='pending'
       and oi.expires_at >= now()
       and lower(oi.email)=v_auth_email;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_organization_invitation_v2(p_token uuid)
 RETURNS TABLE(id uuid, organization_id uuid, organization_name text, email text, role text, expires_at timestamp with time zone, auth_flow text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_auth_email text := lower(coalesce(auth.jwt()->>'email',''));
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  return query
    select oi.id,oi.organization_id,o.name::text,oi.email::text,oi.role::text,oi.expires_at,coalesce(oi.auth_flow,'existing_user')::text
      from public.organization_invitations oi
      join public.organizations o on o.id=oi.organization_id
     where oi.token=p_token
       and oi.status='pending'
       and oi.expires_at>=now()
       and lower(oi.email)=v_auth_email;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_organization_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.owner_id <> auth.uid() then
    raise exception 'owner_id must equal authenticated user';
  end if;
  insert into public.organization_members (organization_id, user_id, role)
  values (new.id, new.owner_id, 'owner')
  on conflict do nothing;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.has_premium_access(p_organization_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if not app_private.is_org_member(p_organization_id) then
    raise exception 'Not authorized to view this organization';
  end if;
  return app_private.is_premium(p_organization_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.import_bank_rows(p_company_id uuid, p_account_name text, p_iban text, p_currency text, p_file_name text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_company public.companies%rowtype; v_account public.bank_accounts%rowtype; v_batch_id uuid; v_row jsonb; v_booking date; v_amount numeric(18,2); v_currency text; v_counterparty text; v_reference text; v_external_id text; v_operation_code text; v_communication text; v_context text; v_description text; v_fingerprint text; v_bank_id uuid; v_source_id uuid; v_total integer:=0; v_imported integer:=0; v_duplicates integer:=0; v_s record; v_import_source text;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select * into v_company from public.companies where id=p_company_id; if not found then raise exception 'Company not found'; end if;
  if not app_private.can_bookkeep_org(v_company.organization_id) then raise exception 'You do not have permission to import bank data for this company'; end if;
  if jsonb_typeof(p_rows)<>'array' then raise exception 'Rows must be an array'; end if; if jsonb_array_length(p_rows)>2500 then raise exception 'Import is limited to 2500 rows at a time'; end if;
  select * into v_account from public.bank_accounts where company_id=p_company_id and ((nullif(trim(p_iban),'') is not null and regexp_replace(coalesce(iban,''),'\s','','g')=regexp_replace(trim(p_iban),'\s','','g')) or (nullif(trim(p_iban),'') is null and lower(name)=lower(trim(p_account_name)))) order by created_at limit 1;
  if not found then insert into public.bank_accounts(organization_id,company_id,name,iban,currency) values(v_company.organization_id,p_company_id,coalesce(nullif(trim(p_account_name),''),'Main bank account'),nullif(trim(p_iban),''),upper(coalesce(nullif(trim(p_currency),''),v_company.base_currency::text,'EUR'))) returning * into v_account; end if;
  insert into public.bank_import_batches(organization_id,company_id,bank_account_id,file_name,imported_by) values(v_company.organization_id,p_company_id,v_account.id,nullif(trim(p_file_name),''),v_uid) returning id into v_batch_id;
  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_total:=v_total+1; begin v_booking:=(v_row->>'booking_date')::date; v_amount:=round((v_row->>'amount')::numeric,2); exception when others then raise exception 'Invalid bank row at position %',v_total; end; if v_amount=0 then continue; end if;
    v_currency:=upper(coalesce(nullif(v_row->>'currency',''),v_account.currency::text,v_company.base_currency::text,'EUR'));
    v_counterparty:=nullif(trim(v_row->>'counterparty_name'),''); v_reference:=nullif(trim(v_row->>'reference'),''); v_external_id:=nullif(trim(v_row->>'external_id'),''); v_operation_code:=nullif(trim(v_row->>'operation_code'),''); v_communication:=nullif(trim(v_row->>'communication'),'');
    v_description:=coalesce(v_reference,v_communication,v_operation_code); v_context:=concat_ws(' ',v_reference,v_communication,v_operation_code,nullif(trim(v_row->>'counterparty_address'),''),nullif(trim(v_row->>'counterparty_iban'),''));
    v_import_source:=coalesce(nullif(trim(v_row->>'source_format'),''),case when lower(coalesce(p_file_name,'')) like '%.pdf' then 'pdf_ai' when lower(coalesce(p_file_name,'')) like '%.xlsx' then 'xlsx' else 'csv' end);
    v_fingerprint:=md5(concat_ws('|',p_company_id::text,v_account.id::text,v_booking::text,v_amount::text,v_currency,coalesce(v_external_id,''),coalesce(v_counterparty,''),coalesce(v_reference,'')));
    v_bank_id:=null;
    insert into public.bank_transactions(organization_id,company_id,bank_account_id,booking_date,value_date,amount,currency,counterparty_name,counterparty_iban,reference,import_source,external_id,match_status,raw_data,import_batch_id,fingerprint)
    values(v_company.organization_id,p_company_id,v_account.id,v_booking,nullif(v_row->>'value_date','')::date,v_amount,v_currency,v_counterparty,nullif(trim(v_row->>'counterparty_iban'),''),v_reference,v_import_source,v_external_id,'unmatched',v_row,v_batch_id,v_fingerprint)
    on conflict do nothing returning id into v_bank_id;
    if v_bank_id is null then v_duplicates:=v_duplicates+1; else
      select * into v_s from app_private.suggest_bank_account(p_company_id,case when v_amount>0 then 'income' else 'expense' end,v_counterparty,v_context);
      insert into public.source_transactions(organization_id,company_id,occurred_on,direction,amount_gross,amount_net,vat_amount,currency,counterparty_name,description,source_type,source_id,classification_status,suggested_account_id,suggestion_confidence,suggestion_reason,suggestion_kind,created_by)
      values(v_company.organization_id,p_company_id,v_booking,case when v_amount>0 then 'income' else 'expense' end,abs(v_amount),abs(v_amount),0,v_currency,v_counterparty,v_description,'bank',v_bank_id,'review',v_s.account_id,v_s.confidence,v_s.reason,v_s.kind,v_uid) returning id into v_source_id;
      v_imported:=v_imported+1;
    end if;
  end loop;
  update public.bank_import_batches set row_count=v_total,imported_count=v_imported,duplicate_count=v_duplicates where id=v_batch_id;
  return jsonb_build_object('batch_id',v_batch_id,'bank_account_id',v_account.id,'rows',v_total,'imported',v_imported,'duplicates',v_duplicates);
end
$function$
;

CREATE OR REPLACE FUNCTION public.issue_service_invoice_draft(p_invoice_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_invoice public.sales_invoices%rowtype;
  v_company public.companies%rowtype;
  v_receivable public.company_accounts%rowtype;
  v_revenue public.company_accounts%rowtype;
  v_vat_account public.company_accounts%rowtype;
  v_period_id uuid;
  v_period_start date;
  v_period_end date;
  v_period_year integer;
  v_entry_id uuid;
  v_entry_number bigint;
  v_year integer;
  v_seq bigint;
  v_invoice_number text;
  v_fx numeric(18,8);
  v_base_currency text;
  v_base_total numeric(18,2);
  v_base_subtotal numeric(18,2);
  v_base_vat numeric(18,2);
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select * into v_invoice from public.sales_invoices where id=p_invoice_id for update;
  if not found then raise exception 'Invoice not found'; end if;
  if v_invoice.status <> 'draft' then raise exception 'Only a draft invoice can be issued'; end if;
  if not app_private.can_bookkeep_org(v_invoice.organization_id) then raise exception 'You do not have permission to issue this invoice'; end if;
  select * into v_company from public.companies where id=v_invoice.company_id;
  if not found then raise exception 'Company not found'; end if;

  if coalesce(v_company.registered_address,'{}'::jsonb)='{}'::jsonb then raise exception 'Complete the registered office address before issuing an invoice'; end if;
  if v_company.vat_registered and nullif(trim(v_company.vat_number),'') is null then raise exception 'Complete the company VAT number before issuing a VAT invoice'; end if;
  if not exists(select 1 from public.sales_invoice_lines where invoice_id=v_invoice.id) then raise exception 'Add at least one invoice line'; end if;

  v_base_currency:=upper(trim(v_company.base_currency::text));
  v_fx:=case when upper(trim(v_invoice.currency))=v_base_currency then 1 else v_invoice.exchange_rate_to_base end;
  if v_fx is null or v_fx<=0 then raise exception 'An exchange rate to the company base currency is required before issuing this invoice'; end if;
  v_base_total:=round(v_invoice.total*v_fx,2);
  v_base_subtotal:=round(v_invoice.subtotal*v_fx,2);
  v_base_vat:=round(v_invoice.vat_total*v_fx,2);

  v_year := extract(year from v_invoice.issue_date)::integer;
  insert into public.invoice_sequences(company_id,fiscal_year,last_number) values(v_company.id,v_year,1)
  on conflict(company_id,fiscal_year) do update set last_number=public.invoice_sequences.last_number+1
  returning last_number into v_seq;
  v_invoice_number := 'INV-'||v_year::text||'-'||lpad(v_seq::text,4,'0');

  select * into v_receivable from public.company_accounts where company_id=v_company.id and code='4011' and is_active=true;
  select * into v_revenue from public.company_accounts where company_id=v_company.id and code='7033' and is_active=true;
  if v_receivable.id is null or v_revenue.id is null then raise exception 'Required customer or revenue ledger account is missing'; end if;
  if v_invoice.vat_total > 0 then
    select * into v_vat_account from public.company_accounts where company_id=v_company.id and code='461411' and is_active=true;
    if v_vat_account.id is null then raise exception 'Output VAT ledger account is missing'; end if;
  end if;

  v_period_year := extract(year from v_invoice.service_date)::integer;
  if extract(month from v_invoice.service_date)::integer < v_company.fiscal_year_start_month then v_period_year := v_period_year - 1; end if;
  v_period_start := make_date(v_period_year,v_company.fiscal_year_start_month,1);
  v_period_end := (v_period_start + interval '1 year - 1 day')::date;
  select id into v_period_id from public.accounting_periods where company_id=v_company.id and starts_on=v_period_start and ends_on=v_period_end and status in ('open','soft_closed') limit 1;
  if v_period_id is null then
    insert into public.accounting_periods(organization_id,company_id,starts_on,ends_on,status)
    values(v_company.organization_id,v_company.id,v_period_start,v_period_end,'open') on conflict(company_id,starts_on,ends_on) do nothing;
    select id into v_period_id from public.accounting_periods where company_id=v_company.id and starts_on=v_period_start and ends_on=v_period_end and status in ('open','soft_closed') limit 1;
  end if;
  if v_period_id is null then raise exception 'The accounting period is closed or locked'; end if;

  perform pg_advisory_xact_lock(hashtextextended(v_company.id::text,0));
  select coalesce(max(entry_number),0)+1 into v_entry_number from public.journal_entries where company_id=v_company.id;
  insert into public.journal_entries(organization_id,company_id,accounting_period_id,entry_number,entry_date,document_date,description,source_type,source_id,status,created_by)
  values(v_company.organization_id,v_company.id,v_period_id,v_entry_number,v_invoice.service_date,v_invoice.issue_date,'Invoice '||v_invoice_number||' — '||coalesce(v_invoice.customer_snapshot->>'name','Customer'),'invoice',v_invoice.id,'draft',v_uid)
  returning id into v_entry_id;

  insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,contact_id,description,debit,credit,currency,exchange_rate,original_currency,original_debit,original_credit)
  values(v_company.organization_id,v_entry_id,v_receivable.id,v_invoice.contact_id,'Customer receivable '||v_invoice_number,v_base_total,0,v_base_currency,v_fx,case when upper(trim(v_invoice.currency))<>v_base_currency then upper(trim(v_invoice.currency)) else null end,case when upper(trim(v_invoice.currency))<>v_base_currency then v_invoice.total else null end,0);
  insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,contact_id,description,debit,credit,currency,exchange_rate,original_currency,original_debit,original_credit)
  values(v_company.organization_id,v_entry_id,v_revenue.id,v_invoice.contact_id,'Service revenue '||v_invoice_number,0,v_base_subtotal,v_base_currency,v_fx,case when upper(trim(v_invoice.currency))<>v_base_currency then upper(trim(v_invoice.currency)) else null end,0,case when upper(trim(v_invoice.currency))<>v_base_currency then v_invoice.subtotal else null end);
  if v_invoice.vat_total > 0 then
    insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,contact_id,description,debit,credit,currency,exchange_rate,vat_code,vat_amount,original_currency,original_debit,original_credit)
    values(v_company.organization_id,v_entry_id,v_vat_account.id,v_invoice.contact_id,'Output VAT '||v_invoice_number,0,v_base_vat,v_base_currency,v_fx,'OUTPUT',v_base_vat,case when upper(trim(v_invoice.currency))<>v_base_currency then upper(trim(v_invoice.currency)) else null end,0,case when upper(trim(v_invoice.currency))<>v_base_currency then v_invoice.vat_total else null end);
  end if;
  perform public.post_journal_entry(v_entry_id);

  update public.sales_invoices set invoice_number=v_invoice_number,status='issued',journal_entry_id=v_entry_id,issued_at=now(),updated_at=now() where id=v_invoice.id;
  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_invoice.organization_id,v_invoice.company_id,v_uid,'invoice.issued','sales_invoice',v_invoice.id,jsonb_build_object('invoice_number',v_invoice_number,'journal_entry_id',v_entry_id,'currency',v_invoice.currency,'exchange_rate_to_base',v_fx));
  return v_invoice.id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.list_organization_invitations(p_organization_id uuid)
 RETURNS TABLE(id uuid, email text, role text, status text, created_at timestamp with time zone, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if not app_private.can_manage_org(p_organization_id) then
    raise exception 'Not authorized to manage this organization';
  end if;
  return query
    select oi.id,oi.email::text,oi.role::text,
           (case when oi.status='pending' and oi.expires_at < now() then 'expired' else oi.status end)::text,
           oi.created_at,oi.expires_at
      from public.organization_invitations oi
     where oi.organization_id=p_organization_id
       and oi.status in ('pending','expired')
     order by oi.created_at desc;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.list_organization_team(p_organization_id uuid)
 RETURNS TABLE(user_id uuid, email text, role text, joined_at timestamp with time zone, is_owner boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if not app_private.is_org_member(p_organization_id) then
    raise exception 'Not authorized to view this organization';
  end if;
  return query
    select om.user_id, coalesce(u.email,'')::text, om.role::text, om.created_at,
           (o.owner_id = om.user_id)
      from public.organization_members om
      join public.organizations o on o.id=om.organization_id
      join auth.users u on u.id=om.user_id
     where om.organization_id=p_organization_id
     order by (o.owner_id=om.user_id) desc, om.created_at asc;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.match_tax_event_payment(p_tax_event_id uuid, p_bank_transaction_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v public.tax_events%rowtype; b public.bank_transactions%rowtype;
begin
 select * into v from public.tax_events where id=p_tax_event_id for update;
 if not found or not app_private.can_account_org(v.organization_id) then raise exception 'Permission denied'; end if;
 select * into b from public.bank_transactions where id=p_bank_transaction_id for update;
 if not found or b.company_id<>v.company_id then raise exception 'Bank transaction not found'; end if;
 if b.amount>=0 then raise exception 'Tax payment must be an outgoing bank movement'; end if;
 if v.amount is not null and abs(abs(b.amount)-v.amount)>0.02 then raise exception 'Bank amount does not match the tax notice amount'; end if;
 update public.tax_events set bank_transaction_id=b.id,status='paid',updated_at=now() where id=v.id;
 update public.compliance_obligations set status='paid',completed_at=now(),updated_at=now() where source_document_id=v.source_document_id and company_id=v.company_id and status not in ('paid','not_applicable');
 insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata) values(v.organization_id,v.company_id,auth.uid(),'tax_payment_matched','tax_event',v.id,jsonb_build_object('bank_transaction_id',b.id,'amount',b.amount));
 return v.id;
end $function$
;

CREATE OR REPLACE FUNCTION public.post_journal_entry(target_entry_id uuid)
 RETURNS public.journal_entries
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  result public.journal_entries;
begin
  update public.journal_entries
  set status = 'posted'
  where id = target_entry_id and status in ('draft','reviewed')
  returning * into result;

  if result.id is null then
    raise exception 'Journal entry not found, not accessible, or cannot be posted';
  end if;

  return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.post_year_end_adjustment(p_company_id uuid, p_fiscal_year integer, p_description text, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_company public.companies%rowtype;
  v_period public.accounting_periods%rowtype;
  v_start date;
  v_end date;
  v_entry_id uuid;
  v_entry_number bigint;
  v_item jsonb;
  v_account public.company_accounts%rowtype;
  v_account_id uuid;
  v_debit numeric(18,2);
  v_credit numeric(18,2);
  v_total_debit numeric(18,2):=0;
  v_total_credit numeric(18,2):=0;
  v_count integer:=0;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if p_fiscal_year<2000 or p_fiscal_year>2100 then raise exception 'Invalid financial year'; end if;
  if length(trim(coalesce(p_description,'')))<3 then raise exception 'Adjustment description is required'; end if;
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)<2 then raise exception 'Add at least two adjustment lines'; end if;

  select * into v_company from public.companies where id=p_company_id;
  if not found or not app_private.can_account_org(v_company.organization_id) then raise exception 'Permission denied'; end if;
  v_start:=make_date(p_fiscal_year,v_company.fiscal_year_start_month,1);
  v_end:=(v_start+interval '1 year - 1 day')::date;

  select * into v_period from public.accounting_periods where company_id=p_company_id and starts_on=v_start and ends_on=v_end for update;
  if found and v_period.status<>'open' then raise exception 'Year-end adjustments require an open financial year'; end if;

  for v_item in select value from jsonb_array_elements(p_lines)
  loop
    begin v_account_id:=(v_item->>'account_id')::uuid; exception when others then raise exception 'Every adjustment line needs a valid account'; end;
    v_debit:=round(coalesce(nullif(v_item->>'debit','')::numeric,0),2);
    v_credit:=round(coalesce(nullif(v_item->>'credit','')::numeric,0),2);
    if v_debit<0 or v_credit<0 or (v_debit>0 and v_credit>0) or (v_debit=0 and v_credit=0) then raise exception 'Each adjustment line must contain either a debit or a credit amount'; end if;
    select * into v_account from public.company_accounts where id=v_account_id and company_id=p_company_id and is_active=true;
    if not found then raise exception 'Adjustment account is unavailable'; end if;
    v_total_debit:=v_total_debit+v_debit;
    v_total_credit:=v_total_credit+v_credit;
    v_count:=v_count+1;
  end loop;
  if v_count<2 or v_total_debit<=0 or abs(v_total_debit-v_total_credit)>.005 then raise exception 'Year-end adjustment must balance: debits % / credits %',v_total_debit,v_total_credit; end if;

  if v_period.id is null then
    insert into public.accounting_periods(organization_id,company_id,starts_on,ends_on,status)
    values(v_company.organization_id,p_company_id,v_start,v_end,'open') returning * into v_period;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text,0));
  select coalesce(max(entry_number),0)+1 into v_entry_number from public.journal_entries where company_id=p_company_id;
  insert into public.journal_entries(organization_id,company_id,accounting_period_id,entry_number,entry_date,document_date,description,source_type,status,created_by)
  values(v_company.organization_id,p_company_id,v_period.id,v_entry_number,v_end,v_end,trim(p_description),'closing','draft',v_uid)
  returning id into v_entry_id;

  for v_item in select value from jsonb_array_elements(p_lines)
  loop
    v_account_id:=(v_item->>'account_id')::uuid;
    v_debit:=round(coalesce(nullif(v_item->>'debit','')::numeric,0),2);
    v_credit:=round(coalesce(nullif(v_item->>'credit','')::numeric,0),2);
    select * into v_account from public.company_accounts where id=v_account_id and company_id=p_company_id;
    insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,description,debit,credit,currency,exchange_rate)
    values(v_company.organization_id,v_entry_id,v_account_id,trim(p_description)||' · '||v_account.code,v_debit,v_credit,v_company.base_currency,1);
  end loop;

  perform public.post_journal_entry(v_entry_id);
  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_company.organization_id,p_company_id,v_uid,'year_end.adjustment_posted','journal_entry',v_entry_id,jsonb_build_object('fiscal_year',p_fiscal_year,'description',trim(p_description),'debit',v_total_debit,'credit',v_total_credit,'line_count',v_count));
  return v_entry_id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.prepare_vat_filing(p_company_id uuid, p_period_start date, p_period_end date)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v_company public.companies%rowtype; v_id uuid; v_output numeric:=0; v_input numeric:=0; v_entries jsonb; v_unposted integer;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select * into v_company from public.companies where id=p_company_id;
 if not found or not app_private.can_account_org(v_company.organization_id) then raise exception 'Permission denied'; end if;
 if not v_company.vat_registered then raise exception 'Company is not VAT registered'; end if;
 if p_period_start is null or p_period_end is null or p_period_end<p_period_start then raise exception 'Invalid VAT period'; end if;
 select count(*) into v_unposted from public.source_transactions where company_id=p_company_id and occurred_on between p_period_start and p_period_end and classification_status<>'posted' and coalesce(vat_amount,0)<>0;
 if v_unposted>0 then raise exception 'VAT filing is not ready: % VAT-bearing transaction(s) are still unposted',v_unposted; end if;
 select coalesce(sum(case when ca.code='461411' then jl.credit-jl.debit else 0 end),0),coalesce(sum(case when ca.code='421611' then jl.debit-jl.credit else 0 end),0),
        coalesce(jsonb_agg(jsonb_build_object('entry_id',je.id,'entry_number',je.entry_number,'entry_date',je.entry_date,'account_code',ca.code,'vat_code',jl.vat_code,'vat_rate',jl.vat_rate,'vat_amount',jl.vat_amount) order by je.entry_number) filter(where ca.code in ('461411','421611')),'[]'::jsonb)
 into v_output,v_input,v_entries
 from public.journal_entries je join public.journal_lines jl on jl.journal_entry_id=je.id join public.company_accounts ca on ca.id=jl.company_account_id where je.company_id=p_company_id and je.status='posted' and je.entry_date between p_period_start and p_period_end;
 insert into public.filings(organization_id,company_id,filing_type,period_label,status,rules_version,payload,ledger_snapshot,created_by,period_start,period_end,snapshot_at,export_status)
 values(v_company.organization_id,p_company_id,'vat_return',to_char(p_period_start,'YYYY-MM-DD')||' → '||to_char(p_period_end,'YYYY-MM-DD'),'draft','LU-VAT-2026.1',jsonb_build_object('output_vat',round(v_output,2),'input_vat',round(v_input,2),'net_vat',round(v_output-v_input,2),'entry_evidence',v_entries,'submission','manual_review_required'),jsonb_build_object('entry_evidence',v_entries),auth.uid(),p_period_start,p_period_end,now(),'review_ready') returning id into v_id;
 insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata) values(v_company.organization_id,p_company_id,auth.uid(),'vat_filing_prepared','filing',v_id,jsonb_build_object('period_start',p_period_start,'period_end',p_period_end,'net_vat',round(v_output-v_input,2)));
 return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.protect_issued_sales_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_has_reversal boolean:=false;
begin
  if current_user in ('postgres','service_role','supabase_admin') and current_setting('compta.bookkeeping_reset',true)='on' then return case when tg_op='DELETE' then old else new end; end if;
  if tg_op='DELETE' and old.status<>'draft' then raise exception 'Issued invoices cannot be deleted directly; use the controlled void or credit-note workflow'; end if;
  if tg_op='UPDATE' and old.status<>'draft' then
    if new.status=old.status and new.id=old.id and new.organization_id=old.organization_id and new.company_id=old.company_id and new.contact_id is not distinct from old.contact_id and new.invoice_number is not distinct from old.invoice_number and new.issue_date=old.issue_date and new.service_date=old.service_date and new.due_date=old.due_date and new.currency=old.currency and new.vat_treatment=old.vat_treatment and new.subtotal=old.subtotal and new.vat_total=old.vat_total and new.total=old.total and new.issuer_snapshot=old.issuer_snapshot and new.customer_snapshot=old.customer_snapshot and new.payment_reference is not distinct from old.payment_reference and new.notes is not distinct from old.notes and new.journal_entry_id is not distinct from old.journal_entry_id and new.created_by is not distinct from old.created_by and new.issued_at is not distinct from old.issued_at and new.created_at=old.created_at and (new.payment_status is distinct from old.payment_status or new.paid_at is distinct from old.paid_at or new.updated_at is distinct from old.updated_at) then return new; end if;
    if old.status='issued' and new.status='void' then
      select exists(select 1 from public.journal_entries r where r.reversal_of=old.journal_entry_id and r.status='posted') into v_has_reversal;
      if v_has_reversal and new.id=old.id and new.organization_id=old.organization_id and new.company_id=old.company_id and new.contact_id is not distinct from old.contact_id and new.invoice_number is not distinct from old.invoice_number and new.issue_date=old.issue_date and new.service_date=old.service_date and new.due_date=old.due_date and new.currency=old.currency and new.vat_treatment=old.vat_treatment and new.subtotal=old.subtotal and new.vat_total=old.vat_total and new.total=old.total and new.issuer_snapshot=old.issuer_snapshot and new.customer_snapshot=old.customer_snapshot and new.payment_reference is not distinct from old.payment_reference and new.notes is not distinct from old.notes and new.journal_entry_id is not distinct from old.journal_entry_id and new.created_by is not distinct from old.created_by and new.issued_at is not distinct from old.issued_at and new.created_at=old.created_at then return new; end if;
    end if;
    raise exception 'Issued invoices are immutable except through controlled payment, correction, void or credit-note workflows';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $function$
;

CREATE OR REPLACE FUNCTION public.protect_issued_sales_invoice_lines()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_invoice_id uuid; v_status text;
begin
  v_invoice_id:=case when tg_op='DELETE' then old.invoice_id else new.invoice_id end;
  select status into v_status from public.sales_invoices where id=v_invoice_id;
  if v_status<>'draft' then raise exception 'Lines on issued invoices are immutable'; end if;
  return case when tg_op='DELETE' then old else new end;
end;$function$
;

CREATE OR REPLACE FUNCTION public.protect_posted_journal_entry_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$ begin if current_user in ('postgres','service_role','supabase_admin') and current_setting('compta.bookkeeping_reset',true)='on' then return old; end if; if old.status in ('posted','locked') then raise exception 'Posted or locked journal entries cannot be deleted; create a reversal instead'; end if; return old; end $function$
;

CREATE OR REPLACE FUNCTION public.protect_posted_journal_lines()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$ declare target_entry_id uuid; entry_status text; begin if current_user in ('postgres','service_role','supabase_admin') and current_setting('compta.bookkeeping_reset',true)='on' then return case when tg_op='DELETE' then old else new end; end if; target_entry_id:=case when tg_op='DELETE' then old.journal_entry_id else new.journal_entry_id end; select status into entry_status from public.journal_entries where id=target_entry_id; if entry_status in ('posted','locked') then raise exception 'Lines belonging to posted or locked journal entries are immutable'; end if; return case when tg_op='DELETE' then old else new end; end $function$
;

CREATE OR REPLACE FUNCTION public.protect_posted_source_transaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$ declare v_has_reversal boolean:=false; begin if current_user in ('postgres','service_role','supabase_admin') and current_setting('compta.bookkeeping_reset',true)='on' then return case when tg_op='DELETE' then old else new end; end if; if old.classification_status='posted' then if old.posted_journal_entry_id is null then raise exception 'Posted source transaction is missing its journal reference'; end if; select exists(select 1 from public.journal_entries r where r.reversal_of=old.posted_journal_entry_id and r.status='posted') into v_has_reversal; if not v_has_reversal then raise exception 'Posted source transactions are immutable; reverse the journal entry instead'; end if; if tg_op='UPDATE' and (new.classification_status not in ('review','reversed') or new.posted_journal_entry_id is not null) then raise exception 'A posted transaction can only be corrected after its original journal entry has been reversed'; end if; end if; return case when tg_op='DELETE' then old else new end; end $function$
;

CREATE OR REPLACE FUNCTION public.reanalyze_pending_source_transactions(p_company_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v_org uuid; v_row record; v_scanned integer:=0; v_suggested integer:=0; v_bulk_ready integer:=0; v_unresolved integer:=0;
begin
  select organization_id into v_org from public.companies where id=p_company_id;
  if v_org is null or not app_private.can_bookkeep_org(v_org) then raise exception 'Permission denied'; end if;
  for v_row in select id from public.source_transactions where company_id=p_company_id and classification_status in ('unclassified','review','classified') order by occurred_on,created_at loop
    perform public.apply_source_transaction_suggestion(v_row.id); v_scanned:=v_scanned+1;
  end loop;
  select count(*) filter(where suggested_account_id is not null), count(*) filter(where suggested_account_id is not null and coalesce(suggestion_confidence,0)>=0.70), count(*) filter(where suggested_account_id is null)
  into v_suggested,v_bulk_ready,v_unresolved
  from public.source_transactions where company_id=p_company_id and classification_status in ('unclassified','review','classified');
  return jsonb_build_object('scanned',v_scanned,'suggested',v_suggested,'bulk_ready',v_bulk_ready,'unresolved',v_unresolved);
end
$function$
;

CREATE OR REPLACE FUNCTION public.recategorize_source_transaction_safe(p_source_transaction_id uuid, p_account_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v_uid uuid:=auth.uid(); v_tx public.source_transactions%rowtype; v_reversal uuid; v_new_entry uuid;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select * into v_tx from public.source_transactions where id=p_source_transaction_id for update;
  if not found then raise exception 'Transaction not found'; end if;
  if not app_private.can_bookkeep_org(v_tx.organization_id) then raise exception 'Permission denied'; end if;
  if v_tx.classification_status<>'posted' or v_tx.posted_journal_entry_id is null then raise exception 'Only posted transactions need accounting-safe recategorisation'; end if;
  v_reversal:=public.reverse_posted_journal_entry(v_tx.posted_journal_entry_id,'Transaction recategorised');
  update public.source_transactions set classification_status='review',posted_journal_entry_id=null,updated_at=now() where id=v_tx.id;
  v_new_entry:=public.classify_and_post_source_transaction(v_tx.id,p_account_code);
  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_tx.organization_id,v_tx.company_id,v_uid,'source_transaction.recategorized','source_transaction',v_tx.id,jsonb_build_object('old_journal_entry_id',v_tx.posted_journal_entry_id,'reversal_entry_id',v_reversal,'replacement_journal_entry_id',v_new_entry,'new_account_code',p_account_code));
  return v_new_entry;
end $function$
;

CREATE OR REPLACE FUNCTION public.record_accountant_profile_event(p_profile_id uuid, p_event_type text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'app_private'
AS $function$
declare
  v_owner uuid;
begin
  if auth.uid() is null then return false; end if;
  if p_event_type not in ('view','email','phone','website') then
    raise exception 'Invalid accountant profile event';
  end if;
  if not app_private.accountant_profile_is_public(p_profile_id) then return false; end if;

  select user_id into v_owner from public.accountant_profiles where id=p_profile_id;
  if v_owner=auth.uid() then return true; end if;

  if exists (
    select 1
    from public.accountant_profile_events
    where profile_id=p_profile_id
      and event_type=p_event_type
      and viewer_user_id=auth.uid()
      and created_at > now() - interval '5 minutes'
  ) then
    return true;
  end if;

  insert into public.accountant_profile_events(profile_id,event_type,viewer_user_id)
  values(p_profile_id,p_event_type,auth.uid());
  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.record_invoice_payment(p_invoice_id uuid, p_amount numeric, p_paid_on date, p_bank_transaction_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_exchange_rate_to_base numeric DEFAULT NULL::numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_invoice public.sales_invoices%rowtype;
  v_company public.companies%rowtype;
  v_bank public.company_accounts%rowtype;
  v_receivable public.company_accounts%rowtype;
  v_fx_gain public.company_accounts%rowtype;
  v_fx_loss public.company_accounts%rowtype;
  v_bank_tx public.bank_transactions%rowtype;
  v_period_id uuid;
  v_period_start date;
  v_period_end date;
  v_period_year integer;
  v_entry_id uuid;
  v_entry_number bigint;
  v_payment_id uuid;
  v_paid_before numeric(18,2);
  v_paid_after numeric(18,2);
  v_description text;
  v_base_currency text;
  v_payment_fx numeric(18,8);
  v_issue_fx numeric(18,8);
  v_payment_base numeric(18,2);
  v_receivable_base numeric(18,2);
  v_fx_difference numeric(18,2);
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Payment amount must be greater than zero'; end if;
  if p_paid_on is null then raise exception 'Payment date is required'; end if;

  select * into v_invoice from public.sales_invoices where id = p_invoice_id for update;
  if not found then raise exception 'Invoice not found'; end if;
  if not app_private.can_bookkeep_org(v_invoice.organization_id) then raise exception 'You do not have permission to record payments for this company'; end if;
  if v_invoice.status <> 'issued' then raise exception 'Only issued invoices can receive payments'; end if;

  select coalesce(sum(amount),0) into v_paid_before from public.invoice_payments where invoice_id = v_invoice.id;
  if v_paid_before >= v_invoice.total then raise exception 'This invoice is already fully paid'; end if;
  if round(v_paid_before + p_amount,2) > round(v_invoice.total,2) then raise exception 'Payment exceeds the outstanding invoice balance'; end if;

  select * into v_company from public.companies where id = v_invoice.company_id;
  if not found then raise exception 'Company not found'; end if;

  v_base_currency:=upper(trim(v_company.base_currency::text));
  v_issue_fx:=case when upper(trim(v_invoice.currency))=v_base_currency then 1 else v_invoice.exchange_rate_to_base end;
  v_payment_fx:=case when upper(trim(v_invoice.currency))=v_base_currency then 1 else p_exchange_rate_to_base end;
  if v_issue_fx is null or v_issue_fx<=0 then raise exception 'The invoice issue exchange rate is missing'; end if;
  if v_payment_fx is null or v_payment_fx<=0 then raise exception 'A payment-date exchange rate is required for this foreign-currency invoice'; end if;

  v_payment_base:=round(p_amount*v_payment_fx,2);
  v_receivable_base:=round(p_amount*v_issue_fx,2);
  v_fx_difference:=round(v_payment_base-v_receivable_base,2);

  select * into v_bank from public.company_accounts where company_id=v_company.id and code='5131' and is_active=true;
  select * into v_receivable from public.company_accounts where company_id=v_company.id and code='4011' and is_active=true;
  select * into v_fx_loss from public.company_accounts where company_id=v_company.id and code='6562' and is_active=true;
  select * into v_fx_gain from public.company_accounts where company_id=v_company.id and code='7562' and is_active=true;
  if v_bank.id is null or v_receivable.id is null then raise exception 'Required bank or customer receivable ledger account is missing'; end if;
  if v_fx_difference<>0 and (v_fx_loss.id is null or v_fx_gain.id is null) then raise exception 'Foreign exchange gain/loss ledger accounts are missing'; end if;

  if p_bank_transaction_id is not null then
    select * into v_bank_tx from public.bank_transactions where id=p_bank_transaction_id for update;
    if not found then raise exception 'Bank transaction not found'; end if;
    if v_bank_tx.company_id <> v_invoice.company_id or v_bank_tx.organization_id <> v_invoice.organization_id then raise exception 'Bank transaction belongs to another company'; end if;
    if v_bank_tx.match_status = 'matched' or v_bank_tx.matched_journal_entry_id is not null then raise exception 'Bank transaction is already matched'; end if;
    if v_bank_tx.amount <= 0 then raise exception 'Invoice payments must be matched to an incoming bank transaction'; end if;
    if upper(trim(v_bank_tx.currency))=upper(trim(v_invoice.currency)) then
      if round(v_bank_tx.amount,2)<>round(p_amount,2) then raise exception 'Bank transaction amount does not match the invoice-currency payment amount'; end if;
    elsif upper(trim(v_bank_tx.currency))=v_base_currency then
      if round(v_bank_tx.amount,2)<>v_payment_base then raise exception 'Base-currency bank amount does not match the converted payment amount'; end if;
    else
      raise exception 'Bank transaction currency is incompatible with this invoice';
    end if;
  end if;

  v_period_year := extract(year from p_paid_on)::integer;
  if extract(month from p_paid_on)::integer < v_company.fiscal_year_start_month then v_period_year := v_period_year - 1; end if;
  v_period_start := make_date(v_period_year, v_company.fiscal_year_start_month, 1);
  v_period_end := (v_period_start + interval '1 year - 1 day')::date;

  select id into v_period_id from public.accounting_periods
   where company_id=v_company.id and starts_on=v_period_start and ends_on=v_period_end and status in ('open','soft_closed') limit 1;
  if v_period_id is null then
    insert into public.accounting_periods(organization_id,company_id,starts_on,ends_on,status)
    values(v_company.organization_id,v_company.id,v_period_start,v_period_end,'open')
    on conflict(company_id,starts_on,ends_on) do nothing;
    select id into v_period_id from public.accounting_periods
     where company_id=v_company.id and starts_on=v_period_start and ends_on=v_period_end and status in ('open','soft_closed') limit 1;
  end if;
  if v_period_id is null then raise exception 'The accounting period is closed or locked'; end if;

  perform pg_advisory_xact_lock(hashtextextended(v_company.id::text,0));
  select coalesce(max(entry_number),0)+1 into v_entry_number from public.journal_entries where company_id=v_company.id;
  v_description := 'Payment ' || coalesce(v_invoice.invoice_number,'invoice') || ' — ' || coalesce(v_invoice.customer_snapshot->>'name','Customer');

  insert into public.journal_entries(
    organization_id,company_id,accounting_period_id,entry_number,entry_date,document_date,description,source_type,source_id,status,created_by
  ) values (
    v_company.organization_id,v_company.id,v_period_id,v_entry_number,p_paid_on,p_paid_on,v_description,'bank',coalesce(p_bank_transaction_id,v_invoice.id),'draft',v_uid
  ) returning id into v_entry_id;

  insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,contact_id,description,debit,credit,currency,exchange_rate,original_currency,original_debit,original_credit)
  values(v_company.organization_id,v_entry_id,v_bank.id,v_invoice.contact_id,v_description,v_payment_base,0,v_base_currency,v_payment_fx,case when upper(trim(v_invoice.currency))<>v_base_currency then upper(trim(v_invoice.currency)) else null end,case when upper(trim(v_invoice.currency))<>v_base_currency then p_amount else null end,0);

  insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,contact_id,description,debit,credit,currency,exchange_rate,original_currency,original_debit,original_credit)
  values(v_company.organization_id,v_entry_id,v_receivable.id,v_invoice.contact_id,v_description,0,v_receivable_base,v_base_currency,v_issue_fx,case when upper(trim(v_invoice.currency))<>v_base_currency then upper(trim(v_invoice.currency)) else null end,0,case when upper(trim(v_invoice.currency))<>v_base_currency then p_amount else null end);

  if v_fx_difference>0 then
    insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,contact_id,description,debit,credit,currency,exchange_rate)
    values(v_company.organization_id,v_entry_id,v_fx_gain.id,v_invoice.contact_id,'Foreign exchange gain',0,v_fx_difference,v_base_currency,1);
  elsif v_fx_difference<0 then
    insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,contact_id,description,debit,credit,currency,exchange_rate)
    values(v_company.organization_id,v_entry_id,v_fx_loss.id,v_invoice.contact_id,'Foreign exchange loss',abs(v_fx_difference),0,v_base_currency,1);
  end if;

  perform public.post_journal_entry(v_entry_id);

  insert into public.invoice_payments(
    organization_id,company_id,invoice_id,bank_transaction_id,paid_on,amount,currency,exchange_rate_to_base,base_amount,reference,journal_entry_id,created_by
  ) values (
    v_company.organization_id,v_company.id,v_invoice.id,p_bank_transaction_id,p_paid_on,round(p_amount,2),v_invoice.currency,v_payment_fx,v_payment_base,nullif(trim(p_reference),''),v_entry_id,v_uid
  ) returning id into v_payment_id;

  v_paid_after := round(v_paid_before + p_amount,2);
  update public.sales_invoices
     set payment_status = case when v_paid_after >= total then 'paid' else 'partially_paid' end,
         paid_at = case when v_paid_after >= total then now() else null end,
         updated_at = now()
   where id = v_invoice.id;

  if p_bank_transaction_id is not null then
    update public.bank_transactions
       set match_status='matched', matched_journal_entry_id=v_entry_id
     where id=p_bank_transaction_id;
  end if;

  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_invoice.organization_id,v_invoice.company_id,v_uid,'invoice.payment_recorded','sales_invoice',v_invoice.id,
    jsonb_build_object('payment_id',v_payment_id,'amount',p_amount,'currency',v_invoice.currency,'payment_exchange_rate',v_payment_fx,'fx_difference',v_fx_difference));

  return v_payment_id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_document_matches(p_document_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  v_doc public.documents%rowtype;
  v_total numeric;
  v_date date;
  v_name text;
  v_currency text;
  v_row record;
  v_score numeric;
  v_count integer:=0;
begin
  select * into v_doc from public.documents where id=p_document_id;
  if not found then raise exception 'Document not found'; end if;
  if not app_private.can_bookkeep_org(v_doc.organization_id) then raise exception 'Permission denied'; end if;

  begin
    v_total:=nullif(v_doc.extracted_data->>'total','')::numeric;
  exception when others then
    v_total:=null;
  end;

  begin
    v_date:=nullif(v_doc.extracted_data->>'document_date','')::date;
  exception when others then
    v_date:=null;
  end;

  v_name:=coalesce(
    nullif(trim(v_doc.extracted_data->>'transaction_counterparty'),''),
    nullif(trim(v_doc.extracted_data->>'issuer_name'),''),
    nullif(trim(v_doc.extracted_data->>'customer_name'),'')
  );

  v_currency:=upper(nullif(trim(v_doc.extracted_data->>'currency'),''));
  if v_currency is not null and v_currency !~ '^[A-Z]{3}$' then
    v_currency:=null;
  end if;

  delete from public.document_transaction_links
  where document_id=v_doc.id
    and status='suggested';

  for v_row in
    select st.*,bt.id as bank_id
    from public.source_transactions st
    left join public.bank_transactions bt
      on st.source_type='bank'
     and bt.id=st.source_id
    where st.company_id=v_doc.company_id
      and st.classification_status not in ('reversed','ignored')
      and (v_currency is null or upper(st.currency)=v_currency)
      and (v_total is null or abs(st.amount_gross-v_total)<=0.02)
      and (v_date is null or st.occurred_on between v_date-7 and v_date+7)
    order by st.occurred_on desc
    limit 20
  loop
    v_score:=0.35;
    if v_currency is not null and upper(v_row.currency)=v_currency then v_score:=v_score+.08; end if;
    if v_total is not null and abs(v_row.amount_gross-v_total)<=0.02 then v_score:=v_score+.37; end if;
    if v_date is not null and v_row.occurred_on=v_date then v_score:=v_score+.15;
    elsif v_date is not null and abs(v_row.occurred_on-v_date)<=3 then v_score:=v_score+.08; end if;
    if coalesce(v_name,'')<>'' and app_private.normalize_counterparty(v_row.counterparty_name) like '%'||split_part(app_private.normalize_counterparty(v_name),' ',1)||'%' then v_score:=v_score+.1; end if;

    insert into public.document_transaction_links(
      organization_id,company_id,document_id,source_transaction_id,bank_transaction_id,
      match_score,status,match_reason,created_by
    )
    values(
      v_doc.organization_id,v_doc.company_id,v_doc.id,v_row.id,v_row.bank_id,
      least(v_score,.99),'suggested',
      case when v_currency is not null
        then 'Matched using currency, amount, date and counterparty evidence.'
        else 'Matched using amount, date and counterparty evidence.'
      end,
      auth.uid()
    )
    on conflict(document_id,source_transaction_id)
      where source_transaction_id is not null
    do update set
      match_score=excluded.match_score,
      match_reason=excluded.match_reason,
      updated_at=now();

    v_count:=v_count+1;
  end loop;

  return v_count;
end
$function$
;

CREATE OR REPLACE FUNCTION public.remove_organization_member(p_organization_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_owner uuid;
begin
  if not app_private.can_manage_org(p_organization_id) then raise exception 'Not authorized'; end if;
  select owner_id into v_owner from public.organizations where id=p_organization_id;
  if p_user_id=v_owner then raise exception 'The organization owner cannot be removed'; end if;
  if p_user_id=auth.uid() then raise exception 'You cannot remove your own access here'; end if;
  delete from public.organization_members where organization_id=p_organization_id and user_id=p_user_id;
  if not found then raise exception 'Member not found'; end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reset_company_bookkeeping(p_company_id uuid, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v_uid uuid:=auth.uid();v_company public.companies%rowtype;v_role text;v_counts jsonb;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select * into v_company from public.companies where id=p_company_id;if not found then raise exception 'Company not found';end if;
  select role into v_role from public.organization_members where organization_id=v_company.organization_id and user_id=v_uid;if v_role<>'owner' then raise exception 'Only the company owner can reset bookkeeping data';end if;
  if trim(p_confirmation)<>v_company.legal_name then raise exception 'Type the exact company legal name to confirm the reset';end if;
  if exists(select 1 from public.accounting_periods where company_id=p_company_id and status in ('closed','locked','hard_closed')) then raise exception 'A closed or locked accounting period exists. Bookkeeping reset is disabled.';end if;
  if exists(select 1 from public.filings where company_id=p_company_id and (status in ('filed','accepted') or export_status='submitted')) then raise exception 'A filed, accepted or submitted declaration exists. Bookkeeping reset is disabled.';end if;
  select jsonb_build_object('transactions',(select count(*) from public.source_transactions where company_id=p_company_id),'journals',(select count(*) from public.journal_entries where company_id=p_company_id),'invoices',(select count(*) from public.sales_invoices where company_id=p_company_id),'bank_rows',(select count(*) from public.bank_transactions where company_id=p_company_id),'filings',(select count(*) from public.filings where company_id=p_company_id)) into v_counts;
  perform set_config('compta.bookkeeping_reset','on',true);
  delete from public.filings where company_id=p_company_id and status not in ('filed','accepted') and export_status<>'submitted';
  delete from public.invoice_payments where company_id=p_company_id;
  delete from public.sales_invoices where company_id=p_company_id;
  delete from public.source_transactions where company_id=p_company_id;
  update public.bank_transactions set matched_journal_entry_id=null where company_id=p_company_id;
  update public.journal_entries set reversal_of=null where company_id=p_company_id;
  delete from public.journal_entries where company_id=p_company_id;
  delete from public.bank_transactions where company_id=p_company_id;
  delete from public.bank_import_batches where company_id=p_company_id;
  update public.accounting_periods set status='open',locked_at=null where company_id=p_company_id and status in ('open','soft_closed');
  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata) values(v_company.organization_id,p_company_id,v_uid,'bookkeeping.reset','company',p_company_id,v_counts);
  return v_counts;
end $function$
;

CREATE OR REPLACE FUNCTION public.reset_financial_year(p_company_id uuid, p_fiscal_year integer, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_company public.companies%rowtype;
  v_role text;
  v_start date;
  v_end date;
  v_counts jsonb;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if p_fiscal_year<2000 or p_fiscal_year>2100 then raise exception 'Invalid financial year'; end if;
  select * into v_company from public.companies where id=p_company_id;
  if not found then raise exception 'Company not found'; end if;
  select role into v_role from public.organization_members where organization_id=v_company.organization_id and user_id=v_uid;
  if v_role<>'owner' then raise exception 'Only the company owner can reset a financial year'; end if;
  if trim(p_confirmation)<>('RESET '||p_fiscal_year::text) then raise exception 'Type RESET % exactly to confirm',p_fiscal_year; end if;
  v_start:=make_date(p_fiscal_year,v_company.fiscal_year_start_month,1);v_end:=(v_start+interval '1 year - 1 day')::date;

  if exists(select 1 from public.accounting_periods where company_id=p_company_id and starts_on=v_start and ends_on=v_end and status in ('closed','locked','hard_closed')) then raise exception 'This financial year is closed or locked and cannot be reset'; end if;
  if exists(select 1 from public.filings where company_id=p_company_id and (period_label=p_fiscal_year::text or (period_start<=v_end and period_end>=v_start)) and (status in ('filed','accepted') or export_status='submitted')) then raise exception 'A filed, accepted or submitted declaration exists for this year. Reset is disabled.'; end if;

  select jsonb_build_object(
    'transactions',(select count(*) from public.source_transactions where company_id=p_company_id and occurred_on between v_start and v_end),
    'journals',(select count(*) from public.journal_entries where company_id=p_company_id and entry_date between v_start and v_end),
    'invoices',(select count(*) from public.sales_invoices where company_id=p_company_id and service_date between v_start and v_end),
    'bank_rows',(select count(*) from public.bank_transactions where company_id=p_company_id and booking_date between v_start and v_end),
    'filings',(select count(*) from public.filings where company_id=p_company_id and (period_label=p_fiscal_year::text or (period_start<=v_end and period_end>=v_start)) and status not in ('filed','accepted') and export_status<>'submitted')
  ) into v_counts;

  perform set_config('compta.bookkeeping_reset','on',true);
  delete from public.filings where company_id=p_company_id and (period_label=p_fiscal_year::text or (period_start<=v_end and period_end>=v_start)) and status not in ('filed','accepted') and export_status<>'submitted';
  delete from public.invoice_payments where company_id=p_company_id and (
    paid_on between v_start and v_end
    or journal_entry_id in (select id from public.journal_entries where company_id=p_company_id and entry_date between v_start and v_end)
    or invoice_id in (select id from public.sales_invoices where company_id=p_company_id and service_date between v_start and v_end)
  );
  delete from public.sales_invoices where company_id=p_company_id and service_date between v_start and v_end;
  delete from public.source_transactions where company_id=p_company_id and occurred_on between v_start and v_end;
  update public.bank_transactions set matched_journal_entry_id=null where company_id=p_company_id and booking_date between v_start and v_end;
  update public.journal_entries set reversal_of=null where company_id=p_company_id and reversal_of in (select id from public.journal_entries where company_id=p_company_id and entry_date between v_start and v_end);
  delete from public.journal_entries where company_id=p_company_id and entry_date between v_start and v_end;
  delete from public.bank_transactions where company_id=p_company_id and booking_date between v_start and v_end;
  delete from public.bank_import_batches b where b.company_id=p_company_id and not exists(select 1 from public.bank_transactions t where t.import_batch_id=b.id);
  update public.accounting_periods set status='open',locked_at=null where company_id=p_company_id and starts_on=v_start and ends_on=v_end and status in ('open','soft_closed');

  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_company.organization_id,p_company_id,v_uid,'bookkeeping.fiscal_year_reset','company',p_company_id,v_counts||jsonb_build_object('fiscal_year',p_fiscal_year));
  return v_counts;
end $function$
;

CREATE OR REPLACE FUNCTION public.reverse_posted_journal_entry(p_entry_id uuid, p_reason text DEFAULT 'Correction'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_entry public.journal_entries%rowtype;
  v_company public.companies%rowtype;
  v_new_id uuid;
  v_new_number bigint;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select * into v_entry from public.journal_entries where id=p_entry_id;
  if not found then raise exception 'Journal entry not found'; end if;
  if v_entry.status <> 'posted' then raise exception 'Only posted journal entries can be reversed'; end if;
  select * into v_company from public.companies where id=v_entry.company_id;
  if not app_private.can_bookkeep_org(v_entry.organization_id) then raise exception 'You do not have permission to reverse this entry'; end if;
  if exists(select 1 from public.journal_entries where reversal_of=v_entry.id and status='posted') then raise exception 'This journal entry has already been reversed'; end if;

  perform pg_advisory_xact_lock(hashtextextended(v_entry.company_id::text,0));
  select coalesce(max(entry_number),0)+1 into v_new_number from public.journal_entries where company_id=v_entry.company_id;

  insert into public.journal_entries(
    organization_id,company_id,accounting_period_id,entry_number,entry_date,document_date,
    description,source_type,source_id,status,reversal_of,created_by
  ) values (
    v_entry.organization_id,v_entry.company_id,v_entry.accounting_period_id,v_new_number,v_entry.entry_date,v_entry.document_date,
    'Reversal · '||coalesce(nullif(trim(p_reason),''),'Correction')||' · '||v_entry.description,
    'reversal',v_entry.source_id,'draft',v_entry.id,v_uid
  ) returning id into v_new_id;

  insert into public.journal_lines(
    organization_id,journal_entry_id,company_account_id,contact_id,description,debit,credit,currency,exchange_rate,vat_code,vat_rate,vat_amount,tax_deductible_percent
  )
  select organization_id,v_new_id,company_account_id,contact_id,'Reversal · '||coalesce(description,''),credit,debit,currency,exchange_rate,vat_code,vat_rate,
         case when vat_amount is null then null else -vat_amount end,tax_deductible_percent
  from public.journal_lines where journal_entry_id=v_entry.id;

  perform public.post_journal_entry(v_new_id);
  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_entry.organization_id,v_entry.company_id,v_uid,'journal.reversed','journal_entry',v_entry.id,jsonb_build_object('reversal_entry_id',v_new_id,'reason',p_reason));
  return v_new_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.revoke_organization_invitation(p_organization_id uuid, p_invitation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if not app_private.can_manage_org(p_organization_id) then raise exception 'Not authorized'; end if;
  update public.organization_invitations
     set status='revoked',revoked_at=now()
   where organization_id=p_organization_id and id=p_invitation_id and status='pending';
  if not found then raise exception 'Invitation not found or already inactive'; end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.save_opening_balance_entry(p_company_id uuid, p_fiscal_year integer, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_company public.companies%rowtype;
  v_period public.accounting_periods%rowtype;
  v_start date;
  v_end date;
  v_entry_id uuid;
  v_entry_number bigint;
  v_item jsonb;
  v_account public.company_accounts%rowtype;
  v_account_id uuid;
  v_debit numeric(18,2);
  v_credit numeric(18,2);
  v_total_debit numeric(18,2):=0;
  v_total_credit numeric(18,2):=0;
  v_count integer:=0;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if p_fiscal_year<2000 or p_fiscal_year>2100 then raise exception 'Invalid financial year'; end if;
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)<2 then raise exception 'Add at least two opening-balance lines'; end if;

  select * into v_company from public.companies where id=p_company_id;
  if not found or not app_private.can_account_org(v_company.organization_id) then raise exception 'Permission denied'; end if;
  v_start:=make_date(p_fiscal_year,v_company.fiscal_year_start_month,1);
  v_end:=(v_start+interval '1 year - 1 day')::date;

  select * into v_period from public.accounting_periods where company_id=p_company_id and starts_on=v_start and ends_on=v_end for update;
  if found and v_period.status in ('closed','locked','hard_closed') then raise exception 'The financial year is closed or locked'; end if;
  if exists(select 1 from public.journal_entries where company_id=p_company_id and entry_date between v_start and v_end and status='posted' and source_type='import' and description='Opening balances · '||p_fiscal_year::text) then raise exception 'Opening balances are already posted for financial year %',p_fiscal_year; end if;

  for v_item in select value from jsonb_array_elements(p_lines)
  loop
    begin v_account_id:=(v_item->>'account_id')::uuid; exception when others then raise exception 'Every opening line needs a valid account'; end;
    v_debit:=round(coalesce(nullif(v_item->>'debit','')::numeric,0),2);
    v_credit:=round(coalesce(nullif(v_item->>'credit','')::numeric,0),2);
    if v_debit<0 or v_credit<0 or (v_debit>0 and v_credit>0) or (v_debit=0 and v_credit=0) then raise exception 'Each opening line must contain either a debit or a credit amount'; end if;
    select * into v_account from public.company_accounts where id=v_account_id and company_id=p_company_id and is_active=true;
    if not found or v_account.account_type not in ('asset','liability','equity') then raise exception 'Opening balances can only use active asset, liability or equity accounts'; end if;
    v_total_debit:=v_total_debit+v_debit;v_total_credit:=v_total_credit+v_credit;v_count:=v_count+1;
  end loop;
  if v_count<2 or v_total_debit<=0 or abs(v_total_debit-v_total_credit)>.005 then raise exception 'Opening position must balance: debits % / credits %',v_total_debit,v_total_credit; end if;

  if v_period.id is null then
    insert into public.accounting_periods(organization_id,company_id,starts_on,ends_on,status) values(v_company.organization_id,p_company_id,v_start,v_end,'open') returning * into v_period;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text,0));
  select coalesce(max(entry_number),0)+1 into v_entry_number from public.journal_entries where company_id=p_company_id;
  insert into public.journal_entries(organization_id,company_id,accounting_period_id,entry_number,entry_date,document_date,description,source_type,status,created_by)
  values(v_company.organization_id,p_company_id,v_period.id,v_entry_number,v_start,v_start,'Opening balances · '||p_fiscal_year::text,'import','draft',v_uid) returning id into v_entry_id;

  for v_item in select value from jsonb_array_elements(p_lines)
  loop
    v_account_id:=(v_item->>'account_id')::uuid;
    v_debit:=round(coalesce(nullif(v_item->>'debit','')::numeric,0),2);
    v_credit:=round(coalesce(nullif(v_item->>'credit','')::numeric,0),2);
    select * into v_account from public.company_accounts where id=v_account_id and company_id=p_company_id;
    insert into public.journal_lines(organization_id,journal_entry_id,company_account_id,description,debit,credit,currency,exchange_rate)
    values(v_company.organization_id,v_entry_id,v_account_id,'Opening balance · '||v_account.code,v_debit,v_credit,v_company.base_currency,1);
  end loop;
  perform public.post_journal_entry(v_entry_id);
  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_company.organization_id,p_company_id,v_uid,'opening_balances.posted','journal_entry',v_entry_id,jsonb_build_object('fiscal_year',p_fiscal_year,'debit',v_total_debit,'credit',v_total_credit,'line_count',v_count));
  return v_entry_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.save_service_invoice_draft(p_company_id uuid, p_invoice_id uuid DEFAULT NULL::uuid, p_customer_name text DEFAULT ''::text, p_customer_email text DEFAULT NULL::text, p_customer_country text DEFAULT 'LU'::text, p_customer_vat_number text DEFAULT NULL::text, p_customer_address jsonb DEFAULT '{}'::jsonb, p_issue_date date DEFAULT CURRENT_DATE, p_service_date date DEFAULT CURRENT_DATE, p_due_date date DEFAULT CURRENT_DATE, p_currency text DEFAULT 'EUR'::text, p_exchange_rate_to_base numeric DEFAULT 1, p_vat_treatment text DEFAULT 'domestic'::text, p_lines jsonb DEFAULT '[]'::jsonb, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_company public.companies%rowtype;
  v_invoice public.sales_invoices%rowtype;
  v_invoice_id uuid;
  v_contact_id uuid;
  v_line jsonb;
  v_line_no integer := 0;
  v_desc text;
  v_qty numeric(18,4);
  v_unit numeric(18,4);
  v_rate numeric(5,2);
  v_net numeric(18,2);
  v_vat numeric(18,2);
  v_gross numeric(18,2);
  v_subtotal numeric(18,2) := 0;
  v_vat_total numeric(18,2) := 0;
  v_total numeric(18,2) := 0;
  v_customer_snapshot jsonb;
  v_issuer_snapshot jsonb;
  v_currency text;
  v_fx numeric(18,8);
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select * into v_company from public.companies where id = p_company_id;
  if not found then raise exception 'Company not found'; end if;
  if not app_private.can_bookkeep_org(v_company.organization_id) then raise exception 'You do not have permission to edit invoices for this company'; end if;

  v_currency:=upper(trim(coalesce(p_currency,v_company.base_currency::text)));
  if v_currency !~ '^[A-Z]{3}$' then raise exception 'Invoice currency must use a three-letter ISO code'; end if;
  v_fx:=case when v_currency=upper(trim(v_company.base_currency::text)) then 1 else p_exchange_rate_to_base end;
  if v_fx is null or v_fx<=0 then raise exception 'An exchange rate to the company base currency is required'; end if;

  if nullif(trim(p_customer_name),'') is null then raise exception 'Customer name is required'; end if;
  if nullif(trim(p_customer_country),'') is null or length(trim(p_customer_country)) <> 2 then raise exception 'Customer country code is required'; end if;
  if coalesce(p_customer_address,'{}'::jsonb) = '{}'::jsonb then raise exception 'Customer address is required'; end if;
  if p_issue_date is null or p_service_date is null or p_due_date is null then raise exception 'Invoice, service and due dates are required'; end if;
  if p_due_date < p_issue_date then raise exception 'Due date cannot be before the invoice date'; end if;
  if p_vat_treatment not in ('domestic','eu_b2b_reverse_charge') then raise exception 'Unsupported VAT treatment'; end if;
  if p_vat_treatment = 'eu_b2b_reverse_charge' then
    if upper(trim(p_customer_country)) = 'LU' then raise exception 'EU reverse charge cannot be used for a Luxembourg customer'; end if;
    if nullif(trim(p_customer_vat_number),'') is null then raise exception 'Customer VAT number is required for EU B2B reverse charge'; end if;
  end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then raise exception 'At least one invoice line is required'; end if;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_line_no := v_line_no + 1;
    v_desc := trim(coalesce(v_line->>'description',''));
    v_qty := coalesce((v_line->>'quantity')::numeric,0);
    v_unit := coalesce((v_line->>'unit_price')::numeric,0);
    v_rate := coalesce((v_line->>'vat_rate')::numeric,0);
    if v_desc = '' then raise exception 'Every invoice line needs a description'; end if;
    if v_qty <= 0 or v_unit < 0 then raise exception 'Invoice quantities and prices are invalid'; end if;
    if p_vat_treatment = 'eu_b2b_reverse_charge' then v_rate := 0; end if;
    if v_rate not in (0,3,8,14,17) then raise exception 'Unsupported Luxembourg VAT rate %', v_rate; end if;
    if p_vat_treatment = 'domestic' and not v_company.vat_registered and v_rate <> 0 then raise exception 'A non-VAT-registered company cannot charge VAT'; end if;
    v_net := round(v_qty * v_unit,2);
    v_vat := round(v_net * v_rate / 100,2);
    v_gross := v_net + v_vat;
    v_subtotal := v_subtotal + v_net;
    v_vat_total := v_vat_total + v_vat;
    v_total := v_total + v_gross;
  end loop;

  select id into v_contact_id
  from public.contacts
  where company_id = v_company.id
    and ((nullif(trim(p_customer_vat_number),'') is not null and upper(coalesce(vat_number,'')) = upper(trim(p_customer_vat_number)))
      or (nullif(trim(p_customer_email),'') is not null and lower(coalesce(email,'')) = lower(trim(p_customer_email))))
  order by created_at asc limit 1;

  if v_contact_id is null then
    insert into public.contacts(organization_id,company_id,type,display_name,legal_name,country_code,vat_number,email,address)
    values(v_company.organization_id,v_company.id,'customer',trim(p_customer_name),trim(p_customer_name),upper(trim(p_customer_country)),nullif(trim(p_customer_vat_number),''),nullif(trim(p_customer_email),''),coalesce(p_customer_address,'{}'::jsonb))
    returning id into v_contact_id;
  else
    update public.contacts set
      display_name=trim(p_customer_name), legal_name=trim(p_customer_name), country_code=upper(trim(p_customer_country)),
      vat_number=nullif(trim(p_customer_vat_number),''), email=nullif(trim(p_customer_email),''), address=coalesce(p_customer_address,'{}'::jsonb), updated_at=now()
    where id=v_contact_id;
  end if;

  v_issuer_snapshot := jsonb_build_object('legal_name',v_company.legal_name,'legal_form',v_company.legal_form,'rcs_number',v_company.rcs_number,'vat_number',v_company.vat_number,'business_permit_number',v_company.business_permit_number,'registered_address',v_company.registered_address);
  v_customer_snapshot := jsonb_build_object('name',trim(p_customer_name),'email',nullif(trim(p_customer_email),''),'country_code',upper(trim(p_customer_country)),'vat_number',nullif(trim(p_customer_vat_number),''),'address',coalesce(p_customer_address,'{}'::jsonb));

  if p_invoice_id is null then
    insert into public.sales_invoices(organization_id,company_id,contact_id,status,payment_status,issue_date,service_date,due_date,currency,exchange_rate_to_base,vat_treatment,subtotal,vat_total,total,issuer_snapshot,customer_snapshot,notes,created_by)
    values(v_company.organization_id,v_company.id,v_contact_id,'draft','unpaid',p_issue_date,p_service_date,p_due_date,v_currency,v_fx,p_vat_treatment,v_subtotal,v_vat_total,v_total,v_issuer_snapshot,v_customer_snapshot,nullif(trim(p_notes),''),v_uid)
    returning id into v_invoice_id;
  else
    select * into v_invoice from public.sales_invoices where id=p_invoice_id for update;
    if not found or v_invoice.company_id <> v_company.id then raise exception 'Draft invoice not found'; end if;
    if v_invoice.status <> 'draft' then raise exception 'Only a draft invoice can be edited directly'; end if;
    v_invoice_id := v_invoice.id;
    update public.sales_invoices set
      contact_id=v_contact_id, issue_date=p_issue_date, service_date=p_service_date, due_date=p_due_date,
      currency=v_currency, exchange_rate_to_base=v_fx, vat_treatment=p_vat_treatment, subtotal=v_subtotal, vat_total=v_vat_total, total=v_total,
      issuer_snapshot=v_issuer_snapshot, customer_snapshot=v_customer_snapshot, notes=nullif(trim(p_notes),''), updated_at=now()
    where id=v_invoice_id;
    delete from public.sales_invoice_lines where invoice_id=v_invoice_id;
  end if;

  v_line_no := 0;
  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_line_no := v_line_no + 1;
    v_desc := trim(v_line->>'description');
    v_qty := (v_line->>'quantity')::numeric;
    v_unit := (v_line->>'unit_price')::numeric;
    v_rate := coalesce((v_line->>'vat_rate')::numeric,0);
    if p_vat_treatment='eu_b2b_reverse_charge' then v_rate:=0; end if;
    v_net:=round(v_qty*v_unit,2); v_vat:=round(v_net*v_rate/100,2); v_gross:=v_net+v_vat;
    insert into public.sales_invoice_lines(organization_id,company_id,invoice_id,line_number,description,quantity,unit_price,vat_rate,net_amount,vat_amount,gross_amount,revenue_account_code)
    values(v_company.organization_id,v_company.id,v_invoice_id,v_line_no,v_desc,v_qty,v_unit,v_rate,v_net,v_vat,v_gross,'7033');
  end loop;

  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_company.organization_id,v_company.id,v_uid,case when p_invoice_id is null then 'invoice.draft_created' else 'invoice.draft_updated' end,'sales_invoice',v_invoice_id,jsonb_build_object('total',v_total,'currency',v_currency,'exchange_rate_to_base',v_fx));
  return v_invoice_id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.set_accounting_period_status(p_company_id uuid, p_fiscal_year integer, p_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  v_company public.companies%rowtype;
  v_start date;
  v_end date;
  v_period public.accounting_periods%rowtype;
  v_blockers integer:=0;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if p_status not in ('open','soft_closed','hard_closed') then raise exception 'Invalid period status'; end if;

  select * into v_company from public.companies where id=p_company_id;
  if not found or not app_private.can_account_org(v_company.organization_id) then raise exception 'Permission denied'; end if;

  v_start:=make_date(p_fiscal_year,v_company.fiscal_year_start_month,1);
  v_end:=(v_start+interval '1 year - 1 day')::date;

  select * into v_period
  from public.accounting_periods
  where company_id=p_company_id and starts_on=v_start and ends_on=v_end
  for update;

  if not found then
    insert into public.accounting_periods(organization_id,company_id,starts_on,ends_on,status)
    values(v_company.organization_id,p_company_id,v_start,v_end,'open')
    returning * into v_period;
  end if;

  if v_period.status='hard_closed' and p_status<>'hard_closed' then
    raise exception 'A hard-closed period cannot be reopened from the application';
  end if;

  if p_status='hard_closed' then
    select
      (select count(*)
         from public.source_transactions
        where company_id=p_company_id
          and occurred_on between v_start and v_end
          and classification_status in ('unclassified','review','classified'))
      +
      (select count(*)
         from public.bank_transactions
        where company_id=p_company_id
          and booking_date between v_start and v_end
          and match_status not in ('matched','ignored'))
      +
      (select count(*)
         from public.sales_invoices
        where company_id=p_company_id
          and service_date between v_start and v_end
          and status='draft')
      +
      (select count(*)
         from public.documents d
        where d.company_id=p_company_id
          and d.extraction_status in ('processing','needs_review','failed')
          and coalesce(
                nullif(d.extracted_data->>'document_date',''),
                nullif(d.extracted_data->>'service_date',''),
                nullif(d.extracted_data->>'issue_date',''),
                nullif(d.extracted_data->>'date','')
              ) ~ '^\d{4}-\d{2}-\d{2}$'
          and coalesce(
                nullif(d.extracted_data->>'document_date',''),
                nullif(d.extracted_data->>'service_date',''),
                nullif(d.extracted_data->>'issue_date',''),
                nullif(d.extracted_data->>'date','')
              )::date between v_start and v_end)
    into v_blockers;

    if v_blockers>0 then
      raise exception 'Year cannot be locked: % unresolved blocker(s) remain',v_blockers;
    end if;
  end if;

  update public.accounting_periods
     set status=p_status,
         locked_at=case when p_status='hard_closed' then now() else null end
   where id=v_period.id;

  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_company.organization_id,p_company_id,auth.uid(),'accounting_period_'||p_status,'accounting_period',v_period.id,jsonb_build_object('fiscal_year',p_fiscal_year,'status',p_status));

  return v_period.id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.suggest_invoice_payment_candidates(p_invoice_id uuid)
 RETURNS TABLE(bank_transaction_id uuid, score numeric, reason text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v public.sales_invoices%rowtype; v_paid numeric; v_outstanding numeric; v_customer text; b record; s numeric; r text;
begin
 select * into v from public.sales_invoices where id=p_invoice_id;
 if not found or not app_private.is_org_member(v.organization_id) then raise exception 'Invoice not found'; end if;
 select coalesce(sum(amount),0) into v_paid from public.invoice_payments where invoice_id=v.id; v_outstanding:=greatest(v.total-v_paid,0);
 v_customer:=app_private.normalize_counterparty(coalesce(v.customer_snapshot->>'name',''));
 for b in select * from public.bank_transactions where company_id=v.company_id and amount>0 and match_status='unmatched' and upper(trim(currency))=upper(trim(v.currency)) order by booking_date desc limit 100 loop
  s:=0;r:='';
  if abs(b.amount-v_outstanding)<=0.02 then s:=s+.62;r:='Exact outstanding amount'; elsif abs(b.amount-v.total)<=0.02 then s:=s+.5;r:='Exact invoice total'; elsif b.amount<=v_outstanding and b.amount>0 then s:=s+.16;r:='Possible partial payment'; end if;
  if v.invoice_number is not null and lower(coalesce(b.reference,'')) like '%'||lower(v.invoice_number)||'%' then s:=s+.25;r:=r||case when r='' then '' else ' · ' end||'Invoice number in bank reference'; end if;
  if v.payment_reference is not null and lower(coalesce(b.reference,'')) like '%'||lower(v.payment_reference)||'%' then s:=s+.28;r:=r||case when r='' then '' else ' · ' end||'Payment reference matches'; end if;
  if v_customer<>'' and app_private.normalize_counterparty(coalesce(b.counterparty_name,''))<>'' and (app_private.normalize_counterparty(b.counterparty_name) like '%'||split_part(v_customer,' ',1)||'%' or v_customer like '%'||split_part(app_private.normalize_counterparty(b.counterparty_name),' ',1)||'%') then s:=s+.12;r:=r||case when r='' then '' else ' · ' end||'Customer name looks consistent'; end if;
  if b.booking_date>=v.issue_date and (v.due_date is null or b.booking_date<=v.due_date+60) then s:=s+.06; end if;
  if s>=.2 then bank_transaction_id:=b.id;score:=least(s,.99);reason:=coalesce(nullif(r,''),'Date/amount candidate');return next;end if;
 end loop;
end
$function$
;

CREATE OR REPLACE FUNCTION public.sync_company_account_translations()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare p record;
begin
  select label_en, label_fr into p from public.pcn_accounts where code = new.code and is_active = true limit 1;
  if found then
    new.label_en := coalesce(new.label_en, p.label_en, new.label);
    new.label_fr := coalesce(new.label_fr, p.label_fr);
  else
    new.label_en := coalesce(new.label_en, new.label);
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_core_compliance_calendar(p_company_id uuid, p_fiscal_year integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_company public.companies%rowtype;
  v_start date;
  v_end date;
  v_count integer := 0;
  v_q integer;
  v_month integer;
  v_period_start date;
  v_due date;
  v_label text := p_fiscal_year::text;
  v_meta jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  select * into v_company from public.companies where id=p_company_id;
  if not found then raise exception 'Company not found'; end if;
  if not app_private.can_account_org(v_company.organization_id) then raise exception 'You do not have permission to update this compliance calendar'; end if;
  if p_fiscal_year < 2000 or p_fiscal_year > 2100 then raise exception 'Invalid fiscal year'; end if;

  v_start := make_date(p_fiscal_year,v_company.fiscal_year_start_month,1);
  v_end := (v_start + interval '1 year - 1 day')::date;

  if v_company.legal_form in ('SARL-S','SARL','SA') then
    insert into public.compliance_obligations(organization_id,company_id,authority,obligation_type,period_label,due_date,status,rule_key,rule_version,metadata)
    values(v_company.organization_id,v_company.id,'RCS','Approve annual accounts & result allocation',v_label,(v_end+interval '6 months')::date,'upcoming','annual_accounts_approval','2026.1',jsonb_build_object('source_url','https://guichet.public.lu/en/entreprises/gestion-juridique-comptabilite/registre-commerce/depots-publications/depot-comptes-annuels.html','year_end',v_end))
    on conflict(company_id,rule_key,period_label) where rule_key is not null do update set due_date=excluded.due_date,rule_version=excluded.rule_version,metadata=excluded.metadata,updated_at=now();
    v_count:=v_count+1;

    insert into public.compliance_obligations(organization_id,company_id,authority,obligation_type,period_label,due_date,status,rule_key,rule_version,metadata)
    values(v_company.organization_id,v_company.id,'RCS','Annual accounts · latest filing date',v_label,(v_end+interval '7 months')::date,'upcoming','annual_accounts_filing','2026.1',jsonb_build_object('source_url','https://guichet.public.lu/en/entreprises/gestion-juridique-comptabilite/registre-commerce/depots-publications/depot-comptes-annuels.html','note','Actual filing is due within one month after approval; this is the latest outer deadline.','year_end',v_end))
    on conflict(company_id,rule_key,period_label) where rule_key is not null do update set due_date=excluded.due_date,rule_version=excluded.rule_version,metadata=excluded.metadata,updated_at=now();
    v_count:=v_count+1;

    if v_company.fiscal_year_start_month=1 then
      insert into public.compliance_obligations(organization_id,company_id,authority,obligation_type,period_label,due_date,status,rule_key,rule_version,metadata)
      values(v_company.organization_id,v_company.id,'ACD','Corporate tax declaration · Model 500',v_label,make_date(p_fiscal_year+1,12,31),'upcoming','model_500','2026.1',jsonb_build_object('source_url','https://impotsdirects.public.lu/fr/echanges_electroniques/decl_coll.html','note','Availability depends on the ACD release of the tax-year procedure/schema.'))
      on conflict(company_id,rule_key,period_label) where rule_key is not null do update set due_date=excluded.due_date,rule_version=excluded.rule_version,metadata=excluded.metadata,updated_at=now();
      v_count:=v_count+1;
    end if;
  end if;

  if v_company.vat_registered and v_company.vat_filing_frequency is not null then
    if v_company.vat_filing_frequency='annual' then
      insert into public.compliance_obligations(organization_id,company_id,authority,obligation_type,period_label,due_date,status,rule_key,rule_version,metadata)
      values(v_company.organization_id,v_company.id,'AED','Annual VAT return',v_label,make_date(p_fiscal_year+1,3,1),'upcoming','vat_annual','2026.1',jsonb_build_object('source_url','https://guichet.public.lu/en/entreprises/fiscalite/impots-benefices/tva/declarations/declaration-tva.html','frequency','annual'))
      on conflict(company_id,rule_key,period_label) where rule_key is not null do update set due_date=excluded.due_date,rule_version=excluded.rule_version,metadata=excluded.metadata,updated_at=now();
      v_count:=v_count+1;
    elsif v_company.vat_filing_frequency='quarterly' then
      for v_q in 1..4 loop
        v_period_start:=make_date(p_fiscal_year,1+(v_q-1)*3,1);
        v_due:=(v_period_start+interval '3 months')::date + 14;
        insert into public.compliance_obligations(organization_id,company_id,authority,obligation_type,period_label,due_date,status,rule_key,rule_version,metadata)
        values(v_company.organization_id,v_company.id,'AED','Quarterly VAT return',p_fiscal_year::text||' Q'||v_q,v_due,'upcoming','vat_quarterly_q'||v_q,'2026.1',jsonb_build_object('source_url','https://guichet.public.lu/en/entreprises/fiscalite/impots-benefices/tva/declarations/declaration-tva.html','frequency','quarterly'))
        on conflict(company_id,rule_key,period_label) where rule_key is not null do update set due_date=excluded.due_date,rule_version=excluded.rule_version,metadata=excluded.metadata,updated_at=now();
        v_count:=v_count+1;
      end loop;
      insert into public.compliance_obligations(organization_id,company_id,authority,obligation_type,period_label,due_date,status,rule_key,rule_version,metadata)
      values(v_company.organization_id,v_company.id,'AED','Annual VAT recap',v_label,make_date(p_fiscal_year+1,5,1),'upcoming','vat_annual','2026.1',jsonb_build_object('source_url','https://guichet.public.lu/en/entreprises/fiscalite/impots-benefices/tva/declarations/declaration-tva.html','frequency','quarterly'))
      on conflict(company_id,rule_key,period_label) where rule_key is not null do update set due_date=excluded.due_date,rule_version=excluded.rule_version,metadata=excluded.metadata,updated_at=now();
      v_count:=v_count+1;
    elsif v_company.vat_filing_frequency='monthly' then
      for v_month in 1..12 loop
        v_period_start:=make_date(p_fiscal_year,v_month,1);
        v_due:=(v_period_start+interval '1 month')::date + 14;
        insert into public.compliance_obligations(organization_id,company_id,authority,obligation_type,period_label,due_date,status,rule_key,rule_version,metadata)
        values(v_company.organization_id,v_company.id,'AED','Monthly VAT return',to_char(v_period_start,'YYYY-MM'),v_due,'upcoming','vat_month_'||lpad(v_month::text,2,'0'),'2026.1',jsonb_build_object('source_url','https://guichet.public.lu/en/entreprises/fiscalite/impots-benefices/tva/declarations/declaration-tva.html','frequency','monthly'))
        on conflict(company_id,rule_key,period_label) where rule_key is not null do update set due_date=excluded.due_date,rule_version=excluded.rule_version,metadata=excluded.metadata,updated_at=now();
        v_count:=v_count+1;
      end loop;
      insert into public.compliance_obligations(organization_id,company_id,authority,obligation_type,period_label,due_date,status,rule_key,rule_version,metadata)
      values(v_company.organization_id,v_company.id,'AED','Annual VAT recap',v_label,make_date(p_fiscal_year+1,5,1),'upcoming','vat_annual','2026.1',jsonb_build_object('source_url','https://guichet.public.lu/en/entreprises/fiscalite/impots-benefices/tva/declarations/declaration-tva.html','frequency','monthly'))
      on conflict(company_id,rule_key,period_label) where rule_key is not null do update set due_date=excluded.due_date,rule_version=excluded.rule_version,metadata=excluded.metadata,updated_at=now();
      v_count:=v_count+1;
    end if;
  end if;

  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.undo_invoice_payment_safe(p_payment_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_payment public.invoice_payments%rowtype;
  v_invoice public.sales_invoices%rowtype;
  v_paid_remaining numeric(18,2);
  v_reversal uuid;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;

  select * into v_payment
  from public.invoice_payments
  where id = p_payment_id
  for update;
  if not found then raise exception 'Payment not found'; end if;

  if not app_private.can_bookkeep_org(v_payment.organization_id) then
    raise exception 'You do not have permission to undo this payment';
  end if;

  select * into v_invoice
  from public.sales_invoices
  where id = v_payment.invoice_id
  for update;
  if not found then raise exception 'Invoice not found'; end if;

  v_reversal := public.reverse_posted_journal_entry(v_payment.journal_entry_id, 'Invoice payment undone');

  if v_payment.bank_transaction_id is not null then
    update public.bank_transactions
       set match_status = 'unmatched', matched_journal_entry_id = null
     where id = v_payment.bank_transaction_id
       and matched_journal_entry_id = v_payment.journal_entry_id;
  end if;

  delete from public.invoice_payments where id = v_payment.id;

  select coalesce(sum(amount),0)
    into v_paid_remaining
  from public.invoice_payments
  where invoice_id = v_invoice.id;

  update public.sales_invoices
     set payment_status = case
           when round(v_paid_remaining,2) >= round(total,2) then 'paid'
           when v_paid_remaining > 0 then 'partially_paid'
           else 'unpaid'
         end,
         paid_at = case when round(v_paid_remaining,2) >= round(total,2) then paid_at else null end,
         updated_at = now()
   where id = v_invoice.id;

  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_payment.organization_id,v_payment.company_id,v_uid,'invoice_payment_undone','invoice_payment',v_payment.id,
         jsonb_build_object('invoice_id',v_payment.invoice_id,'amount',v_payment.amount,'journal_entry_id',v_payment.journal_entry_id,'reversal_entry_id',v_reversal));

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_compliance_obligation_status(p_obligation_id uuid, p_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare v public.compliance_obligations%rowtype;
begin
  if p_status not in ('upcoming','action_required','ready','filed','paid','overdue','not_applicable') then
    raise exception 'Invalid compliance status';
  end if;

  select * into v from public.compliance_obligations where id = p_obligation_id for update;
  if not found or not app_private.can_account_org(v.organization_id) then raise exception 'Permission denied'; end if;

  update public.compliance_obligations
  set status = p_status,
      completed_at = case when p_status in ('filed','paid','not_applicable') then now() else null end,
      updated_at = now()
  where id = v.id;

  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v.organization_id,v.company_id,auth.uid(),'compliance_status_changed','compliance_obligation',v.id,jsonb_build_object('status',p_status));
  return v.id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.update_organization_member_role(p_organization_id uuid, p_user_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_owner uuid;
begin
  if not app_private.can_manage_org(p_organization_id) then raise exception 'Not authorized'; end if;
  if p_role not in ('admin','accountant','bookkeeper','viewer') then raise exception 'Invalid role'; end if;
  select owner_id into v_owner from public.organizations where id=p_organization_id;
  if p_user_id=v_owner then raise exception 'The organization owner role cannot be changed'; end if;
  update public.organization_members set role=p_role
   where organization_id=p_organization_id and user_id=p_user_id;
  if not found then raise exception 'Member not found'; end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_source_transaction_safe(p_source_transaction_id uuid, p_occurred_on date, p_direction text, p_amount_gross numeric, p_vat_amount numeric, p_counterparty_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_tx public.source_transactions%rowtype;
  v_account_code text;
  v_old jsonb;
  v_reversal uuid;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select * into v_tx from public.source_transactions where id=p_source_transaction_id for update;
  if not found then raise exception 'Transaction not found'; end if;
  if not app_private.can_bookkeep_org(v_tx.organization_id) then raise exception 'You do not have permission to edit this transaction'; end if;
  if p_direction not in ('income','expense') then raise exception 'Choose income or expense'; end if;
  if p_amount_gross is null or p_amount_gross<=0 then raise exception 'Gross amount must be greater than zero'; end if;
  if coalesce(p_vat_amount,0)<0 or coalesce(p_vat_amount,0)>p_amount_gross then raise exception 'VAT must be between zero and gross amount'; end if;
  v_old:=to_jsonb(v_tx);

  if v_tx.classification_status='posted' and v_tx.posted_journal_entry_id is not null then
    select code into v_account_code from public.company_accounts where id=v_tx.suggested_account_id;
    if v_account_code is null then raise exception 'The original accounting category is missing'; end if;
    v_reversal:=public.reverse_posted_journal_entry(v_tx.posted_journal_entry_id,'Transaction corrected');
  end if;

  update public.source_transactions set
    occurred_on=p_occurred_on,
    direction=p_direction,
    amount_gross=round(p_amount_gross,2),
    vat_amount=round(coalesce(p_vat_amount,0),2),
    amount_net=round(p_amount_gross-coalesce(p_vat_amount,0),2),
    counterparty_name=nullif(trim(p_counterparty_name),''),
    description=nullif(trim(p_description),''),
    classification_status=case when v_account_code is null then 'review' else 'review' end,
    posted_journal_entry_id=null,
    updated_at=now()
  where id=v_tx.id;

  if v_account_code is not null then
    perform public.classify_and_post_source_transaction(v_tx.id,v_account_code);
  end if;

  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_tx.organization_id,v_tx.company_id,v_uid,'source_transaction.updated','source_transaction',v_tx.id,jsonb_build_object('before',v_old,'reversal_entry_id',v_reversal));
  return v_tx.id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_journal_posting()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare total_debit numeric(20,4); total_credit numeric(20,4);
begin
  if current_user in ('postgres','service_role','supabase_admin') and current_setting('compta.bookkeeping_reset',true)='on' then return new; end if;
  if old.status in ('posted','locked') then raise exception 'Posted or locked journal entries are immutable; create a reversal instead'; end if;
  if new.status in ('posted','locked') and old.status not in ('posted','locked') then
    select coalesce(sum(debit),0),coalesce(sum(credit),0) into total_debit,total_credit from public.journal_lines where journal_entry_id=new.id;
    if total_debit=0 or total_credit=0 or total_debit<>total_credit then raise exception 'Journal entry must be balanced before posting (debits %, credits %)',total_debit,total_credit; end if;
    new.posted_at=coalesce(new.posted_at,now());
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.void_sales_invoice_safe(p_invoice_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_invoice public.sales_invoices%rowtype;
  v_reversal uuid;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select * into v_invoice from public.sales_invoices where id=p_invoice_id for update;
  if not found then raise exception 'Invoice not found'; end if;
  if not app_private.can_bookkeep_org(v_invoice.organization_id) then raise exception 'You do not have permission to void this invoice'; end if;
  if v_invoice.status='void' then raise exception 'Invoice is already void'; end if;
  if exists(select 1 from public.invoice_payments where invoice_id=v_invoice.id) then raise exception 'A paid or partially paid invoice must be corrected with a credit-note workflow'; end if;
  if v_invoice.status='issued' and v_invoice.journal_entry_id is not null then
    v_reversal:=public.reverse_posted_journal_entry(v_invoice.journal_entry_id,'Invoice voided '||coalesce(v_invoice.invoice_number,''));
  end if;
  update public.sales_invoices set status='void',payment_status='unpaid',updated_at=now() where id=v_invoice.id;
  insert into public.audit_events(organization_id,company_id,actor_user_id,event_type,entity_type,entity_id,metadata)
  values(v_invoice.organization_id,v_invoice.company_id,v_uid,'invoice.voided','sales_invoice',v_invoice.id,jsonb_build_object('invoice_number',v_invoice.invoice_number,'reversal_entry_id',v_reversal));
  return v_reversal;
end;
$function$
;

