  using (((classification_status <> 'posted'::text) AND (EXISTS ( SELECT 1
   FROM public.organization_members m
  WHERE ((m.organization_id = source_transactions.organization_id) AND (m.user_id = ( SELECT auth.uid() AS uid)) AND (m.role = ANY (ARRAY['owner'::text, 'admin'::text, 'accountant'::text, 'bookkeeper'::text])))))));
create policy source_transactions_insert on public.source_transactions as permissive for insert to authenticated
  with check (((created_by = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM public.organization_members m
  WHERE ((m.organization_id = source_transactions.organization_id) AND (m.user_id = ( SELECT auth.uid() AS uid)) AND (m.role = ANY (ARRAY['owner'::text, 'admin'::text, 'accountant'::text, 'bookkeeper'::text]))))) AND (EXISTS ( SELECT 1
   FROM public.companies c
  WHERE ((c.id = source_transactions.company_id) AND (c.organization_id = source_transactions.organization_id))))));
