  using ((EXISTS ( SELECT 1
   FROM public.organization_members m
  WHERE ((m.organization_id = source_transactions.organization_id) AND (m.user_id = ( SELECT auth.uid() AS uid))))));
create policy source_transactions_update on public.source_transactions as permissive for update to authenticated
  using (((classification_status <> ALL (ARRAY['posted'::text, 'reversed'::text])) AND (EXISTS ( SELECT 1
   FROM public.organization_members m
  WHERE ((m.organization_id = source_transactions.organization_id) AND (m.user_id = auth.uid()) AND (m.role = ANY (ARRAY['owner'::text, 'admin'::text, 'accountant'::text, 'bookkeeper'::text])))))))
  with check (((classification_status <> ALL (ARRAY['posted'::text, 'reversed'::text])) AND (EXISTS ( SELECT 1
   FROM public.organization_members m
  WHERE ((m.organization_id = source_transactions.organization_id) AND (m.user_id = auth.uid()) AND (m.role = ANY (ARRAY['owner'::text, 'admin'::text, 'accountant'::text, 'bookkeeper'::text]))))) AND (EXISTS ( SELECT 1
   FROM public.companies c
  WHERE ((c.id = source_transactions.company_id) AND (c.organization_id = source_transactions.organization_id))))));
