-- ---------------------------------------------------------------------------
-- Comments
-- ---------------------------------------------------------------------------
comment on column public.company_accounts.label_en is 'English display label for this company account.';
comment on column public.company_accounts.label_fr is 'French display label for this company account; falls back to the base label when unavailable.';
comment on column public.source_transactions.ai_classification is 'Structured AI bookkeeping suggestion and evidence metadata. Advisory until posted through normal accounting controls.';
comment on column public.user_profiles.locale is 'Per-user UI and generated-document language preference. Supported values: en, fr.';
comment on function public.consume_password_recovery_rate_limit(text,integer,integer) is 'Server-only atomic rate limiter for password-recovery requests; bucket keys must be hashed identifiers.';
comment on function public.consume_security_rate_limit(text) is 'Atomically applies conservative per-user limits to authenticated expensive actions.';
comment on function public.current_user_requires_mfa() is 'Returns true when the current authenticated session is below AAL2 and the user has opted in with a verified MFA factor.';
comment on table public.accountant_reviewers is 'Server-only registry of users allowed to approve or reject accountant directory profiles.';
comment on table public.early_access_allowed_emails is 'Server-only access registry used to grandfather existing users and approve early-access invitees.';
comment on table public.early_access_reviewers is 'Server-only registry of users authorized to review and invite early-access applicants.';
comment on table public.early_access_waitlist is 'Public early-access requests. Public clients may insert only; review and invitation are server-only.';
comment on table public.transactional_email_deliveries is 'Server-only idempotency ledger for transactional email delivery. Recipient and message bodies are deliberately not retained.';

-- ---------------------------------------------------------------------------
-- Storage buckets (policies on storage.objects are in the row level security section)
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('accountant-profiles', 'accountant-profiles', true, 5242880, '{image/jpeg,image/png,image/webp}'::text[]) on conflict (id) do nothing;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('company-documents', 'company-documents', false, 26214400, '{application/pdf,image/jpeg,image/png,image/webp,text/csv}'::text[]) on conflict (id) do nothing;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('user-avatars', 'user-avatars', false, 5242880, '{image/jpeg,image/png,image/webp}'::text[]) on conflict (id) do nothing;
